import React, { useMemo, useState } from 'react';
import { Check, ChevronDown, ChevronUp, Minus } from 'lucide-react';
import {
  DEFAULT_SENSITIVE_CATEGORIES,
  getAllSelectionKeys,
  getCategorySelectionKeys,
  getDisplayFieldCount,
  getSensitiveField,
  makeSelectionKey,
  type SensitiveCategory,
  type SensitiveField,
  type SensitiveMatcher,
} from './desensitizeRules';

type DefaultRuleSettingsPanelProps = {
  /** 已选 UI 勾选键（categoryId::fieldId）；复用字段按分类独立 */
  selectedKeys: string[];
  onChange: (keys: string[]) => void;
  categories?: SensitiveCategory[];
};

function getMatcherLabel(
  matcher: SensitiveMatcher,
  regexIndex?: number,
  regexTotal?: number
): string {
  if (matcher.type === 'semantic') return '语义';
  if (regexTotal && regexTotal > 1 && regexIndex) return `正则 ${regexIndex}`;
  return '正则';
}

function MatcherLabelChip({
  label,
  isRegex,
}: {
  label: string;
  isRegex: boolean;
}) {
  return (
    <span
      className={`shrink-0 rounded px-1.5 py-0.5 text-[10px] font-extrabold leading-none ${
        isRegex
          ? 'bg-sky-50 text-sky-600 ring-1 ring-inset ring-sky-200'
          : 'bg-cyan-50 text-cyan-700 ring-1 ring-inset ring-cyan-200'
      }`}
    >
      {label}
    </span>
  );
}

function MatcherDetailRow({
  matcher,
  regexIndex,
  regexTotal,
}: {
  matcher: SensitiveMatcher;
  regexIndex?: number;
  regexTotal?: number;
}) {
  const isRegex = matcher.type === 'regex';
  const label = getMatcherLabel(matcher, regexIndex, regexTotal);
  return (
    <div className="flex min-w-0 items-start gap-1.5">
      <MatcherLabelChip label={label} isRegex={isRegex} />
      <span className="min-w-0 break-all text-[11px] font-medium leading-relaxed text-slate-500">
        {matcher.value}
      </span>
    </div>
  );
}

type AnnotatedMatcher = {
  matcher: SensitiveMatcher;
  regexIndex?: number;
  regexTotal: number;
  label: string;
};

function annotateMatchers(matchers: SensitiveMatcher[]): AnnotatedMatcher[] {
  const regexTotal = matchers.filter((m) => m.type === 'regex').length;
  let regexIndex = 0;
  return matchers.map((matcher) => {
    const currentRegexIndex = matcher.type === 'regex' ? ++regexIndex : undefined;
    return {
      matcher,
      regexIndex: currentRegexIndex,
      regexTotal,
      label: getMatcherLabel(matcher, currentRegexIndex, regexTotal),
    };
  });
}

function SelectionCheckbox({
  checked,
  indeterminate,
  onChange,
  ariaLabel,
}: {
  checked: boolean;
  indeterminate?: boolean;
  onChange: () => void;
  ariaLabel: string;
}) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={indeterminate ? 'mixed' : checked}
      aria-label={ariaLabel}
      onClick={(e) => {
        e.stopPropagation();
        onChange();
      }}
      className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 transition-colors ${
        checked || indeterminate
          ? 'border-rose-600 bg-rose-600 text-white'
          : 'border-slate-300 bg-white hover:border-rose-300'
      }`}
    >
      {indeterminate ? (
        <Minus size={12} strokeWidth={3} />
      ) : checked ? (
        <Check size={12} strokeWidth={3} />
      ) : null}
    </button>
  );
}

const DefaultRuleSettingsPanel: React.FC<DefaultRuleSettingsPanelProps> = ({
  selectedKeys,
  onChange,
  categories = DEFAULT_SENSITIVE_CATEGORIES,
}) => {
  const [expandedIds, setExpandedIds] = useState<string[]>(() =>
    categories[0] ? [categories[0].id] : []
  );
  const selectedSet = useMemo(() => new Set(selectedKeys), [selectedKeys]);

  const allKeys = useMemo(() => getAllSelectionKeys(categories), [categories]);
  const displayTotal = useMemo(() => getDisplayFieldCount(categories), [categories]);
  const displaySelected = useMemo(
    () => allKeys.filter((key) => selectedSet.has(key)).length,
    [allKeys, selectedSet]
  );

  const allSelected = allKeys.length > 0 && allKeys.every((key) => selectedSet.has(key));
  const someSelected = !allSelected && allKeys.some((key) => selectedSet.has(key));
  const allExpanded = categories.length > 0 && categories.every((c) => expandedIds.includes(c.id));

  const getCategoryStats = (category: SensitiveCategory) => {
    const keys = getCategorySelectionKeys(category);
    const selected = keys.filter((key) => selectedSet.has(key)).length;
    return {
      keys,
      selected,
      total: keys.length,
      all: keys.length > 0 && selected === keys.length,
      some: selected > 0 && selected < keys.length,
    };
  };

  const setKeys = (next: Set<string>) => {
    onChange(Array.from(next));
  };

  const toggleAll = () => {
    if (allSelected) setKeys(new Set());
    else setKeys(new Set(allKeys));
  };

  const toggleCategory = (category: SensitiveCategory) => {
    const stats = getCategoryStats(category);
    const next = new Set(selectedSet);
    if (stats.all) {
      stats.keys.forEach((key) => next.delete(key));
    } else {
      stats.keys.forEach((key) => next.add(key));
    }
    setKeys(next);
  };

  const toggleField = (categoryId: string, fieldId: string) => {
    const key = makeSelectionKey(categoryId, fieldId);
    const next = new Set(selectedSet);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    setKeys(next);
  };

  const toggleExpanded = (categoryId: string) => {
    setExpandedIds((prev) =>
      prev.includes(categoryId) ? prev.filter((id) => id !== categoryId) : [...prev, categoryId]
    );
  };

  const expandAll = () => {
    setExpandedIds(categories.map((c) => c.id));
  };

  const collapseAll = () => {
    setExpandedIds([]);
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col animate-in fade-in slide-in-from-right-4 duration-200">
      <div className="mb-4 flex items-center justify-between gap-3 px-1">
        <div className="flex items-center gap-3 min-w-0">
          <SelectionCheckbox
            checked={allSelected}
            indeterminate={someSelected}
            onChange={toggleAll}
            ariaLabel="全选敏感字段"
          />
          <p className="text-[13px] font-bold text-slate-700">
            已选{' '}
            <span className="text-rose-600">
              {displaySelected} / {displayTotal}
            </span>{' '}
            个敏感字段
          </p>
        </div>
        <button
          type="button"
          onClick={allExpanded ? collapseAll : expandAll}
          className="shrink-0 text-[12px] font-bold text-rose-600 hover:text-rose-700 transition-colors"
        >
          {allExpanded ? '全部收起' : '全部展开'}
        </button>
      </div>

      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto custom-scrollbar pr-1">
        {categories.map((category) => {
          const stats = getCategoryStats(category);
          const expanded = expandedIds.includes(category.id);
          return (
            <div key={category.id} className="relative">
              {/*
                吸顶层用方形不透明底（bg-white）盖住圆角外侧，
                防止内容区左右描边从圆角缺口穿出顶部。
              */}
              <div className="sticky top-0 z-10 bg-white">
                <div
                  className={`flex items-center gap-3 px-4 py-3.5 ${
                    expanded
                      ? 'rounded-t-2xl border border-b-0 border-rose-200 bg-rose-50'
                      : 'rounded-2xl border border-slate-200 bg-slate-50/80'
                  }`}
                >
                  <SelectionCheckbox
                    checked={stats.all}
                    indeterminate={stats.some}
                    onChange={() => toggleCategory(category)}
                    ariaLabel={`选择${category.name}`}
                  />
                  <button
                    type="button"
                    onClick={() => toggleExpanded(category.id)}
                    className="flex min-w-0 flex-1 items-center gap-2 text-left"
                  >
                    <span className="truncate text-[14px] font-extrabold text-slate-800">
                      {category.name}
                    </span>
                    <span className="shrink-0 text-[12px] font-bold text-slate-400">
                      {stats.selected}/{stats.total}
                    </span>
                  </button>
                  <button
                    type="button"
                    onClick={() => toggleExpanded(category.id)}
                    className="rounded-lg p-1 text-slate-400 transition-colors hover:bg-white/80 hover:text-slate-600"
                    aria-label={expanded ? '收起' : '展开'}
                  >
                    {expanded ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>

              {expanded ? (
                <div className="relative z-0 rounded-b-2xl border border-t-0 border-rose-200 bg-white divide-y divide-slate-100">
                  {category.fieldIds.map((fieldId) => {
                    const field = getSensitiveField(fieldId);
                    if (!field) return null;
                    const key = makeSelectionKey(category.id, fieldId);
                    return (
                      <FieldRow
                        key={key}
                        field={field}
                        checked={selectedSet.has(key)}
                        onToggle={() => toggleField(category.id, fieldId)}
                      />
                    );
                  })}
                </div>
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
};

function FieldRow({
  field,
  checked,
  onToggle,
}: {
  field: SensitiveField;
  checked: boolean;
  onToggle: () => void;
}) {
  const [regexExpanded, setRegexExpanded] = useState(false);
  const annotated = useMemo(() => annotateMatchers(field.matchers), [field.matchers]);
  const regexItems = annotated.filter((item) => item.matcher.type === 'regex');
  const semanticItems = annotated.filter((item) => item.matcher.type === 'semantic');
  /** 正则超过 2 条：前 2 条默认展示详情，其余收起；展开后显示全部 */
  const hasExtraRegex = regexItems.length > 2;
  const visibleRegexItems = hasExtraRegex && !regexExpanded ? regexItems.slice(0, 2) : regexItems;
  const hiddenRegexCount = Math.max(0, regexItems.length - visibleRegexItems.length);

  return (
    <div className="flex items-start gap-3 px-4 py-3.5">
      <div className="pt-0.5">
        <SelectionCheckbox
          checked={checked}
          onChange={onToggle}
          ariaLabel={`选择${field.name}`}
        />
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-[13px] font-extrabold text-slate-800">{field.name}</span>
          {field.builtin ? (
            <span className="rounded-full bg-white px-2 py-0.5 text-[10px] font-bold text-rose-600 ring-1 ring-inset ring-rose-200">
              系统内置
            </span>
          ) : null}
        </div>

        <div className="mt-2 space-y-1.5">
          {visibleRegexItems.map((item, idx) => (
            <MatcherDetailRow
              key={`${field.id}-regex-${idx}`}
              matcher={item.matcher}
              regexIndex={item.regexIndex}
              regexTotal={item.regexTotal}
            />
          ))}

          {hasExtraRegex && !regexExpanded ? (
            <div className="flex flex-wrap items-center gap-1.5">
              <span className="text-[10px] font-bold text-slate-400">+{hiddenRegexCount}</span>
              <button
                type="button"
                onClick={() => setRegexExpanded(true)}
                className="text-[11px] font-bold text-rose-600 hover:text-rose-700 transition-colors"
              >
                展开详情
              </button>
            </div>
          ) : null}

          {hasExtraRegex && regexExpanded ? (
            <button
              type="button"
              onClick={() => setRegexExpanded(false)}
              className="text-[11px] font-bold text-rose-600 hover:text-rose-700 transition-colors"
            >
              收起
            </button>
          ) : null}

          {semanticItems.map((item, idx) => (
            <MatcherDetailRow
              key={`${field.id}-semantic-${idx}`}
              matcher={item.matcher}
              regexIndex={item.regexIndex}
              regexTotal={item.regexTotal}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

export default DefaultRuleSettingsPanel;
