const ELLIPSIS = '……';

function getMeasureContext(font: string): CanvasRenderingContext2D | null {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  ctx.font = font;
  return ctx;
}

function countWrappedLines(ctx: CanvasRenderingContext2D, text: string, maxWidth: number): number {
  if (!text) return 0;
  if (maxWidth <= 0) return 1;

  let lines = 1;
  let line = '';
  for (const ch of text) {
    const next = line + ch;
    if (ctx.measureText(next).width > maxWidth && line) {
      lines += 1;
      line = ch;
    } else {
      line = next;
    }
  }
  return lines;
}

/** 按容器宽度将命中正文截断为最多 maxLines 行，前缀（如「全网匹配：」）始终保留 */
export function fitHitSnippetBody(
  prefix: string,
  body: string,
  containerWidth: number,
  font: string,
  maxLines = 2
): string {
  if (!body || containerWidth <= 0) return body;

  const ctx = getMeasureContext(font);
  if (!ctx) return body;

  const full = `${prefix}${body}`;
  if (countWrappedLines(ctx, full, containerWidth) <= maxLines) return body;

  let lo = 0;
  let hi = body.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    const trial = `${prefix}${body.slice(0, mid)}${ELLIPSIS}`;
    if (countWrappedLines(ctx, trial, containerWidth) <= maxLines) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }

  if (lo >= body.length) return body;
  return `${body.slice(0, lo)}${ELLIPSIS}`;
}
