export type QuestionOption = {
  id: string;
  label: string;
};

export type OnboardingQuestion = {
  id: string;
  title: string;
  hint?: string;
  required: boolean;
  /** single：单选；multi：多选；form：结构化表单 */
  inputType: 'single' | 'multi' | 'form';
  options?: QuestionOption[];
  /** form 内附带多选区块的标题 */
  optionsLabel?: string;
  /** form 内多选区块是否排在表单字段之前 */
  optionsBeforeFields?: boolean;
  /** form 类型的字段定义 */
  formFields?: Array<{
    id: string;
    label: string;
    placeholder?: string;
    kind: 'text' | 'select';
    options?: QuestionOption[];
  }>;
  /** 多选时是否允许自定义补充 */
  allowCustom?: boolean;
  customPlaceholder?: string;
};

