export type PlaybookAnswers = Record<
  string,
  {
    optionIds?: string[];
    customText?: string;
    formValues?: Record<string, string>;
    skipped?: boolean;
  }
>;

export type ContractPlaybook = {
  id: string;
  name: string;
  desc: string;
  createdAt: string;
  updatedAt: string;
  answers: PlaybookAnswers;
  /** true 表示系统默认手册，不可删除 */
  isDefault?: boolean;
};

export const DEFAULT_PLAYBOOK: ContractPlaybook = {
  id: 'default',
  name: '默认审查手册',
  desc: '采用系统默认规则：中等偏保守风险偏好，标准责任上限与上报触发条件。点击即可直接开启审查。',
  createdAt: '',
  updatedAt: '',
  answers: {},
  isDefault: true,
};

const CONTRACT_FOCUS_LABELS: Record<string, string> = {
  procurement: '采购/供应商',
  sales: '销售/客户',
  saas: 'SaaS/订阅',
  nda: 'NDA/保密',
  general: '通用',
};

const RISK_LABELS: Record<string, string> = {
  conservative: '保守',
  moderate: '中等',
  flexible: '灵活',
};

const REVIEW_STANCE_LABELS: Record<string, string> = {
  buyer_customer: '采购方/客户',
  seller_supplier: '销售方/供货方',
  both_confirm_each_time: '双向通用',
  neutral_structure: '中立结构审查',
};

/** 根据答案生成手册名称与摘要 */
export function buildPlaybookMeta(answers: PlaybookAnswers): { name: string; desc: string } {
  const focusId = answers.contract_focus?.optionIds?.[0];
  const riskId = answers.risk_appetite?.optionIds?.[0];
  const audienceId = answers.audience?.optionIds?.[0];
  const stanceId = answers.review_stance?.optionIds?.[0];

  const focusLabel = (focusId && CONTRACT_FOCUS_LABELS[focusId]) || '自定义';
  const riskLabel = (riskId && RISK_LABELS[riskId]) || '';

  const name = riskLabel
    ? `${focusLabel}审查手册（${riskLabel}）`
    : `${focusLabel}审查手册`;

  const parts: string[] = [];
  if (focusId) parts.push(`合同类型：${CONTRACT_FOCUS_LABELS[focusId] || focusId}`);
  if (riskId) parts.push(`风险偏好：${RISK_LABELS[riskId] || riskId}`);
  if (stanceId) parts.push(`审查立场：${REVIEW_STANCE_LABELS[stanceId] || stanceId}`);
  if (audienceId) {
    const aud = REQUIRED_ONBOARDING_QUESTIONS.find((q) => q.id === 'audience')?.options?.find(
      (o) => o.id === audienceId
    );
    if (aud) parts.push(`受众：${aud.label}`);
  }
  const escalateCount = answers.escalation_and_approval?.optionIds?.length || 0;
  if (escalateCount > 0) parts.push(`必报事项 ${escalateCount} 项`);

  return {
    name,
    desc: parts.length > 0 ? parts.join(' · ') : '基于问卷回答生成的审查规则手册',
  };
}

function isAnswerFilled(a: PlaybookAnswers[string] | undefined): boolean {
  if (!a || a.skipped) return false;
  if (a.optionIds && a.optionIds.length > 0) return true;
  if (a.customText && a.customText.trim()) return true;
  if (a.formValues && Object.values(a.formValues).some((v) => v && String(v).trim())) return true;
  return false;
}

/** 是否至少回答过一道题（非全部跳过） */
export function hasAnyAnswer(answers: PlaybookAnswers): boolean {
  return Object.values(answers).some(isAnswerFilled);
}

export function countFilledAnswers(answers: PlaybookAnswers): number {
  return Object.values(answers).filter(isAnswerFilled).length;
}

export function createPlaybookFromAnswers(answers: PlaybookAnswers): ContractPlaybook {
  const { name, desc } = buildPlaybookMeta(answers);
  const now = new Date().toISOString();
  return {
    id: `pb_${Date.now()}`,
    name,
    desc,
    createdAt: now,
    updatedAt: now,
    answers,
  };
}

export function updatePlaybookFromAnswers(
  playbook: ContractPlaybook,
  answers: PlaybookAnswers
): ContractPlaybook {
  const { name, desc } = buildPlaybookMeta(answers);
  return {
    ...playbook,
    name,
    desc,
    answers,
    updatedAt: new Date().toISOString(),
  };
}

const STORAGE_KEY = 'lvaiduo_contract_playbooks';
const ONBOARDING_SEEN_KEY = 'lvaiduo_contract_onboarding_seen';

export function loadPlaybooks(): ContractPlaybook[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function savePlaybooks(playbooks: ContractPlaybook[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(playbooks));
}

export function hasSeenOnboarding(): boolean {
  return localStorage.getItem(ONBOARDING_SEEN_KEY) === '1';
}

export function markOnboardingSeen() {
  localStorage.setItem(ONBOARDING_SEEN_KEY, '1');
}
