import React, { useEffect, useMemo, useState } from 'react';
import { FileText, Sparkles, X } from 'lucide-react';
import type { ConversationTurn } from './conversationTurns';
import type { ReferenceSourceItem } from './mockSearchResult';
import {
  defaultReportSourceScope,
  resolveTurnUserQuestion,
  type ReportSourceScope,
} from './searchReport';

export type SearchReportModalProps = {
  open: boolean;
  onClose: () => void;
  turn: ConversationTurn | null;
  turnLabel: string;
  submittedQuery: string;
  allTurnSources: ReferenceSourceItem[];
  citedSources: ReferenceSourceItem[];
  filteredSources: ReferenceSourceItem[] | null;
  showFilteredScopeOption: boolean;
  onGenerate?: (scope: ReportSourceScope, sourceCount: number) => void;
};

const SCOPE_OPTIONS: { key: ReportSourceScope; label: string; desc: (n: number) => string }[] = [
  {
    key: 'cited',
    label: '本轮引用来源',
    desc: (n) => `回答中已标注引用的 ${n} 条来源`,
  },
  {
    key: 'all_turn',
    label: '本轮全部参考来源',
    desc: (n) => `该轮回答关联的全部 ${n} 条参考来源`,
  },
  {
    key: 'filtered',
    label: '当前筛选结果',
    desc: (n) => `右侧当前筛选条件下的 ${n} 条来源`,
  },
];

const SearchReportModal: React.FC<SearchReportModalProps> = ({
  open,
  onClose,
  turn,
  turnLabel,
  submittedQuery,
  allTurnSources,
  citedSources,
  filteredSources,
  showFilteredScopeOption,
  onGenerate,
}) => {
  const [sourceScope, setSourceScope] = useState<ReportSourceScope>('cited');

  const userQuestion = turn ? resolveTurnUserQuestion(turn, submittedQuery) : '';

  const scopeCounts = useMemo(
    () => ({
      cited: citedSources.length,
      all_turn: allTurnSources.length,
      filtered: filteredSources?.length ?? 0,
    }),
    [citedSources.length, allTurnSources.length, filteredSources]
  );

  useEffect(() => {
    if (!open || !turn) return;
    setSourceScope(defaultReportSourceScope(citedSources));
  }, [open, turn, citedSources]);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, onClose]);

  if (!open || !turn) return null;

  const answerPreview =
    turn.answerMarkdown.trim().slice(0, 160) +
    (turn.answerMarkdown.length > 160 ? '…' : '');

  const visibleScopeOptions = SCOPE_OPTIONS.filter(
    (o) => o.key !== 'filtered' || (showFilteredScopeOption && filteredSources && filteredSources.length > 0)
  );

  const selectedCount =
    sourceScope === 'cited'
      ? scopeCounts.cited
      : sourceScope === 'filtered'
        ? scopeCounts.filtered
        : scopeCounts.all_turn;

  const handleGenerate = () => {
    onGenerate?.(sourceScope, selectedCount);
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/40 p-4 backdrop-blur-sm animate-in fade-in"
      onClick={onClose}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="search-report-modal-title"
        className="flex max-h-[min(88vh,720px)] w-full max-w-lg flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl animate-in zoom-in-95"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between border-b border-slate-100 px-5 py-4">
          <div className="flex items-center gap-2.5">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-50 text-blue-600">
              <Sparkles size={18} strokeWidth={2.25} />
            </div>
            <div>
              <h2 id="search-report-modal-title" className="text-[15px] font-extrabold text-slate-900">
                生成检索报告
              </h2>
              <p className="text-[11px] font-bold text-blue-600">{turnLabel}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-slate-500 transition hover:bg-slate-100 hover:text-slate-800"
            aria-label="关闭"
          >
            <X size={18} strokeWidth={2.25} />
          </button>
        </div>

        <div className="custom-scrollbar flex-1 space-y-4 overflow-y-auto px-5 py-4">
          <section className="rounded-xl border border-slate-100 bg-slate-50/80 p-3.5">
            <p className="mb-2 text-[11px] font-extrabold uppercase tracking-wide text-slate-400">
              报告上下文（本轮）
            </p>
            <dl className="space-y-2 text-[12px]">
              <div>
                <dt className="font-bold text-slate-500">用户问题</dt>
                <dd className="mt-0.5 font-medium leading-relaxed text-slate-800">{userQuestion}</dd>
              </div>
              <div>
                <dt className="font-bold text-slate-500">AI 回答摘要</dt>
                <dd className="mt-0.5 line-clamp-3 font-medium leading-relaxed text-slate-700">
                  {answerPreview || '（无回答内容）'}
                </dd>
              </div>
              <div className="flex flex-wrap gap-3 pt-1 text-[11px] font-bold text-slate-500">
                <span>
                  引用来源 <span className="tabular-nums text-slate-800">{scopeCounts.cited}</span>
                </span>
                <span>
                  全部参考 <span className="tabular-nums text-slate-800">{scopeCounts.all_turn}</span>
                </span>
              </div>
            </dl>
            <p className="mt-2.5 text-[10px] font-medium leading-relaxed text-slate-400">
              报告将基于本轮问答生成；左侧勾选来源不影响本弹框默认范围（勾选仅用于追问、收录等操作）。
            </p>
          </section>

          <section>
            <p className="mb-2.5 text-[12px] font-extrabold text-slate-800">来源范围</p>
            <div className="space-y-2">
              {visibleScopeOptions.map((opt) => {
                const count =
                  opt.key === 'cited'
                    ? scopeCounts.cited
                    : opt.key === 'filtered'
                      ? scopeCounts.filtered
                      : scopeCounts.all_turn;
                const disabled = count === 0;
                const active = sourceScope === opt.key;
                return (
                  <label
                    key={opt.key}
                    className={`flex cursor-pointer gap-3 rounded-xl border px-3.5 py-3 transition ${
                      disabled
                        ? 'cursor-not-allowed border-slate-100 bg-slate-50/50 opacity-50'
                        : active
                          ? 'border-blue-200 bg-blue-50/60 ring-1 ring-blue-100'
                          : 'border-slate-200 bg-white hover:border-slate-300'
                    }`}
                  >
                    <input
                      type="radio"
                      name="report-source-scope"
                      className="mt-0.5 shrink-0 accent-blue-600"
                      checked={active}
                      disabled={disabled}
                      onChange={() => setSourceScope(opt.key)}
                    />
                    <span className="min-w-0 flex-1">
                      <span className="flex items-center gap-2 text-[13px] font-extrabold text-slate-800">
                        <FileText size={14} className="shrink-0 text-blue-600" aria-hidden />
                        {opt.label}
                        <span className="tabular-nums text-[11px] font-bold text-slate-500">
                          {count}
                        </span>
                      </span>
                      <span className="mt-0.5 block text-[11px] font-medium text-slate-500">
                        {opt.desc(count)}
                      </span>
                    </span>
                  </label>
                );
              })}
            </div>
          </section>
        </div>

        <div className="flex justify-end gap-2 border-t border-slate-100 px-5 py-3.5">
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-[12px] font-extrabold text-slate-700 transition hover:bg-slate-50"
          >
            取消
          </button>
          <button
            type="button"
            disabled={selectedCount === 0}
            onClick={handleGenerate}
            className="rounded-xl bg-blue-600 px-4 py-2 text-[12px] font-extrabold text-white shadow-sm transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-40"
          >
            生成报告
          </button>
        </div>
      </div>
    </div>
  );
};

export default SearchReportModal;
