import React, { useEffect, useRef, useState } from 'react';
import {
  ChevronDown,
  ChevronRight,
  BookOpen,
  FileSearch,
  FileText,
  Globe,
  Search,
  Send,
  X,
} from 'lucide-react';
import type { SearchMode, SearchSourceKey, SearchSources } from './useSearchLogic';

const MODE_TABS: { id: SearchMode; label: string; badge?: string }[] = [
  { id: 'normal', label: '普通' },
  { id: 'deep', label: '深入' },
  { id: 'research', label: '深度研究', badge: 'NEW' },
];

type SearchInputProps = {
  value: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  searchMode: SearchMode;
  onSearchModeChange: (mode: SearchMode) => void;
  sources: SearchSources;
  onToggleSource: (key: SearchSourceKey) => void;
  placeholder?: string;
  /** 结果页底部追问：单行紧凑条 + 图标来源 */
  variant?: 'default' | 'embedded';
  /** 右侧已选参考来源数量；>0 时在输入框上方展示引用提示 */
  selectedReferenceCount?: number;
  /** 清空已选参考来源（与来源栏「清空选择」一致） */
  onClearSelectedReferences?: () => void;
};

const sourceConfig: { key: SearchSourceKey; label: string; icon: React.ReactNode }[] = [
  { key: 'web', label: '全网', icon: <Globe size={16} strokeWidth={2.25} /> },
  { key: 'fabao', label: '法宝数据库', icon: <FileText size={16} strokeWidth={2.25} /> },
  { key: 'knowledge', label: '知识库', icon: <BookOpen size={16} strokeWidth={2.25} /> },
];

/** 底部条用略大图标，仅图形无文字 */
const sourceConfigEmbedded: { key: SearchSourceKey; label: string; icon: React.ReactNode }[] = [
  { key: 'web', label: '全网', icon: <Globe size={18} strokeWidth={2} /> },
  { key: 'fabao', label: '法宝数据库', icon: <BookOpen size={18} strokeWidth={2} /> },
  { key: 'knowledge', label: '知识库', icon: <FileSearch size={18} strokeWidth={2} /> },
];

/** 结果页底部追问条：低于该宽度时改为「模式在上 + 双行输入 + 来源/发送」布局 */
const EMBEDDED_COMPACT_MAX_WIDTH_PX = 560;
/** 再窄时来源与发送单独一行，避免与双行输入挤在同一行 */
const EMBEDDED_STACK_ACTIONS_MAX_WIDTH_PX = 440;

const SearchInput: React.FC<SearchInputProps> = ({
  value,
  onChange,
  onSubmit,
  searchMode,
  onSearchModeChange,
  sources,
  onToggleSource,
  placeholder = '您有什么想要了解的问题？',
  variant = 'default',
  selectedReferenceCount = 0,
  onClearSelectedReferences,
}) => {
  const embedded = variant === 'embedded';
  const embeddedWrapRef = useRef<HTMLDivElement>(null);
  const [embeddedCompact, setEmbeddedCompact] = useState(false);
  const [embeddedStackActions, setEmbeddedStackActions] = useState(false);

  useEffect(() => {
    if (!embedded) return;
    const el = embeddedWrapRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => {
      const w = entry?.contentRect.width ?? 0;
      if (w <= 0) return;
      setEmbeddedCompact(w < EMBEDDED_COMPACT_MAX_WIDTH_PX);
      setEmbeddedStackActions(w < EMBEDDED_STACK_ACTIONS_MAX_WIDTH_PX);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [embedded]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit();
  };

  const modeSelect = (
    <div className="relative flex shrink-0 items-center rounded-xl border border-indigo-100/90 bg-indigo-50/90 py-1 pl-2 pr-7">
      <Search size={15} className="pointer-events-none shrink-0 text-indigo-500" aria-hidden />
      <select
        value={searchMode}
        onChange={(e) => onSearchModeChange(e.target.value as SearchMode)}
        className="max-w-[7rem] cursor-pointer appearance-none bg-transparent py-1 pl-1 text-[12px] font-extrabold text-indigo-900 outline-none"
        aria-label="检索模式"
      >
        {MODE_TABS.map((tab) => (
          <option key={tab.id} value={tab.id}>
            {tab.label}
          </option>
        ))}
      </select>
      <ChevronDown
        size={14}
        className="pointer-events-none absolute right-1.5 top-1/2 -translate-y-1/2 text-indigo-400"
        aria-hidden
      />
    </div>
  );

  const sourceButtonsEmbedded = (
    <div className="flex shrink-0 items-center gap-1">
      {sourceConfigEmbedded.map(({ key, label, icon }) => {
        const on = sources[key];
        return (
          <button
            key={key}
            type="button"
            title={label}
            aria-label={label}
            aria-pressed={on}
            onClick={() => onToggleSource(key)}
            className={`flex h-9 w-9 items-center justify-center rounded-lg border transition-all ${
              on
                ? 'border-blue-400 bg-blue-50 text-blue-600 shadow-sm'
                : 'border-slate-200 bg-white text-slate-400 hover:border-slate-300 hover:text-slate-500'
            }`}
          >
            {icon}
          </button>
        );
      })}
    </div>
  );

  const hasInput = value.trim().length > 0;

  const sendButtonEmbedded = (
    <button
      type="submit"
      className={[
        'flex h-9 shrink-0 items-center gap-1.5 rounded-xl px-3.5 text-[13px] font-extrabold text-white transition-all md:px-4',
        hasInput
          ? 'bg-blue-600 shadow-sm shadow-blue-200/50 hover:bg-blue-700 active:scale-[0.98]'
          : 'bg-[#8ea5ff] hover:brightness-105 active:scale-[0.98]',
      ].join(' ')}
    >
      <Send size={15} strokeWidth={2.5} className="-rotate-12" />
      发送
    </button>
  );

  const hasReferenceContext = selectedReferenceCount > 0;
  const embeddedShellClass =
    'overflow-hidden rounded-2xl border border-slate-200/90 bg-white shadow-sm ring-1 ring-slate-100/80 transition-all focus-within:border-blue-300/80 focus-within:ring-2 focus-within:ring-blue-400/20';

  const referenceHintBar = hasReferenceContext ? (
    <div
      className="flex items-center gap-2 border-b border-slate-100 bg-slate-50/95 px-3 py-2"
      role="status"
      aria-live="polite"
    >
      <ChevronRight className="h-3.5 w-3.5 shrink-0 text-slate-400" aria-hidden />
      <FileText className="h-3.5 w-3.5 shrink-0 text-blue-600" aria-hidden />
      <p className="min-w-0 flex-1 truncate text-[12px] font-bold text-slate-700">
        已选 <span className="tabular-nums text-blue-700">{selectedReferenceCount}</span> 个来源
        <span className="font-medium text-slate-500"> · 可继续追问，仅基于所选来源回答</span>
      </p>
      {onClearSelectedReferences ? (
        <button
          type="button"
          onClick={onClearSelectedReferences}
          className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md text-slate-400 transition hover:bg-slate-200/80 hover:text-slate-700"
          aria-label="清空已选来源"
        >
          <X size={14} strokeWidth={2.25} />
        </button>
      ) : null}
    </div>
  ) : null;

  if (embedded) {
    return (
      <div ref={embeddedWrapRef} className="w-full">
        <form onSubmit={handleSubmit}>
          {embeddedCompact ? (
            <div
              className={`flex flex-col gap-2 ${embeddedShellClass} ${
                hasReferenceContext ? '' : 'px-2.5 py-2.5 md:px-3'
              }`}
            >
              {referenceHintBar}
              <div
                className={`flex flex-col gap-2 ${hasReferenceContext ? 'px-2.5 py-2.5 md:px-3' : ''}`}
              >
              <div
                className={`flex min-h-0 gap-2 ${embeddedStackActions ? 'flex-col' : 'flex-row items-end'}`}
              >
                <textarea
                  value={value}
                  onChange={(e) => onChange(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      onSubmit();
                    }
                  }}
                  placeholder={placeholder}
                  rows={2}
                  autoComplete="off"
                  className="min-h-[52px] min-w-0 flex-1 resize-none rounded-xl border border-slate-100 bg-slate-50/80 px-3 py-2 text-[14px] font-bold leading-snug text-slate-800 outline-none transition placeholder:font-medium placeholder:text-slate-400 focus:border-blue-200 focus:bg-white focus:ring-1 focus:ring-blue-100"
                />
                <div
                  className={`flex shrink-0 flex-wrap items-center gap-1.5 ${
                    embeddedStackActions ? 'w-full justify-between pt-0.5' : 'pb-0.5'
                  }`}
                >
                  {modeSelect}
                  <div className="flex flex-wrap items-center gap-1.5">
                    {!hasReferenceContext ? sourceButtonsEmbedded : null}
                    {sendButtonEmbedded}
                  </div>
                </div>
              </div>
              </div>
            </div>
          ) : (
            <div className={embeddedShellClass}>
              {referenceHintBar}
              <div className="flex h-[52px] items-center gap-1.5 px-2 md:gap-2 md:px-3">
              {modeSelect}
              <input
                type="text"
                value={value}
                onChange={(e) => onChange(e.target.value)}
                placeholder={placeholder}
                autoComplete="off"
                className="min-w-0 flex-1 border-0 bg-transparent py-2 text-[14px] font-bold text-slate-800 outline-none placeholder:font-medium placeholder:text-slate-400"
              />
              {!hasReferenceContext ? sourceButtonsEmbedded : null}
              {sendButtonEmbedded}
              </div>
            </div>
          )}
        </form>
        <p className="mt-2 text-center text-[11px] font-medium text-slate-400">
          内容由 AI 生成，仅供参考
        </p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-3xl mx-auto">
      <div className="flex flex-wrap items-center gap-2 mb-3">
        {MODE_TABS.map((tab) => {
          const active = searchMode === tab.id;
          return (
            <button
              key={tab.id}
              type="button"
              onClick={() => onSearchModeChange(tab.id)}
              className={`inline-flex items-center gap-1.5 rounded-xl px-4 py-2 text-[13px] font-extrabold transition-all ${
                active
                  ? 'bg-blue-600 text-white shadow-md shadow-blue-200/50'
                  : 'bg-white/90 text-slate-600 border border-slate-200/90 hover:border-blue-200 hover:bg-blue-50/80'
              }`}
            >
              {tab.label}
              {tab.badge ? (
                <span
                  className={`rounded-md px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wide ${
                    active ? 'bg-white/25 text-white' : 'bg-orange-100 text-orange-600'
                  }`}
                >
                  {tab.badge}
                </span>
              ) : null}
            </button>
          );
        })}
      </div>

      <form onSubmit={handleSubmit}>
        <div className="rounded-2xl border border-slate-200/90 bg-white shadow-lg shadow-slate-200/50 ring-1 ring-slate-100/80 overflow-hidden transition-all focus-within:ring-2 focus-within:ring-blue-400/30 focus-within:border-blue-300/80">
          <textarea
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder={placeholder}
            rows={5}
            autoComplete="off"
            className="w-full resize-none bg-transparent px-5 pt-4 pb-3 text-[15px] font-bold text-slate-800 placeholder:text-slate-400 placeholder:font-medium outline-none min-h-[140px]"
          />

          <div className="flex flex-col gap-3 border-t border-slate-100 px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex flex-wrap items-center gap-2">
              {sourceConfig.map(({ key, label, icon }) => {
                const on = sources[key];
                return (
                  <button
                    key={key}
                    type="button"
                    onClick={() => onToggleSource(key)}
                    className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[12px] font-bold transition-all ${
                      on
                        ? 'border-blue-200 bg-blue-50 text-blue-700 shadow-sm'
                        : 'border-slate-200 bg-slate-50 text-slate-500 hover:border-slate-300'
                    }`}
                  >
                    <span className={on ? 'text-blue-600' : 'text-slate-400'}>{icon}</span>
                    {label}
                  </button>
                );
              })}
            </div>

            <button
              type="submit"
              className={[
                'inline-flex shrink-0 items-center justify-center gap-2 self-end rounded-xl px-6 py-2.5 text-[13px] font-extrabold text-white transition-all sm:self-auto',
                hasInput
                  ? 'bg-blue-600 shadow-md shadow-blue-200/50 hover:bg-blue-700 active:scale-[0.98]'
                  : 'bg-[#8ea5ff] hover:brightness-105 active:scale-[0.98]',
              ].join(' ')}
            >
              <Send size={16} strokeWidth={2.5} className="-rotate-12" />
              发送
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default SearchInput;
