const EFFECT_STATUS_LABEL_TO_KEY: Record<string, LawEffectStatusFilter> = {
  现行有效: 'effective',
  尚未生效: 'not_yet_effective',
  已修改: 'amended',
  已废止: 'repealed',
};

const HIERARCHY_LABEL_TO_KEY: Record<string, LawHierarchyKey> = {
  法律: 'statute',
  行政法规: 'admin_regulation',
  司法解释: 'judicial_interpretation',
  部门规章: 'department_rule',
  地方性法规: 'local_regulation',
  规范性文件: 'normative_doc',
};

export function isLawRegulationMaterial(item: ReferenceSourceItem): boolean {
  return item.sourceType === 'law' || item.sourceType === 'judicial_interpretation';
}

export function isCaseJudgmentMaterial(item: ReferenceSourceItem): boolean {
  return item.sourceType === 'case' || item.sourceType === 'judgment';
}

export function resolveItemCaseReferenceLevel(item: ReferenceSourceItem): CaseReferenceLevelKey | null {
  if (item.caseReferenceLevel) return item.caseReferenceLevel;
  if (item.fabaoDbKey === 'guiding') return 'guiding';
  if (item.fabaoDbKey === 'court_case') return 'court_db';
  if (item.fabaoDbKey === 'typical') return 'typical';
  if (
    item.databaseName?.includes('公报') ||
    item.sourceLibraryName?.includes('公报') ||
    item.title.includes('公报')
  ) {
    return 'gazette';
  }
  if (item.sourceType === 'judgment') return 'ordinary_judgment';
  if (item.fabaoDbKey === 'case') return 'ordinary_judgment';
  if (item.sourceType === 'case') return 'typical';
  return null;
}

export function resolveItemCaseCourtLevel(item: ReferenceSourceItem): CaseCourtLevelKey | null {
  if (item.caseCourtLevel) return item.caseCourtLevel;
  const court = item.court ?? item.metaLineParts?.[0] ?? '';
  if (!court) return null;
  if (court.includes('最高人民法院') || court === '最高院') return 'supreme';
  if (court.includes('高级')) return 'high';
  if (court.includes('中级')) return 'intermediate';
  if (court.includes('人民法院')) return 'basic';
  return null;
}

export function resolveItemCaseTrialProcedure(item: ReferenceSourceItem): CaseTrialProcedureKey | null {
  if (item.caseTrialProcedure) return item.caseTrialProcedure;
  const text = `${item.title} ${item.metaLineParts?.join(' ') ?? ''}`;
  if (text.includes('执行')) return 'enforcement';
  if (text.includes('再审')) return 'retrial';
  if (text.includes('二审')) return 'second_instance';
  if (text.includes('一审')) return 'first_instance';
  return 'first_instance';
}

function parseJudgmentDate(item: ReferenceSourceItem): Date | null {
  if (item.judgmentDate) {
    const d = new Date(item.judgmentDate);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  if (item.year && /^\d{4}$/.test(item.year)) {
    const d = new Date(`${item.year}-06-15`);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function matchesCaseJudgmentTime(item: ReferenceSourceItem, range: CaseJudgmentTimeRange): boolean {
  if (range === 'all') return true;
  const date = parseJudgmentDate(item);
  if (!date) return true;

  const now = new Date();
  const years = range === 'y1' ? 1 : range === 'y3' ? 3 : 5;
  const cutoff = new Date(now);
  cutoff.setFullYear(cutoff.getFullYear() - years);
  return date >= cutoff;
}

function isCaseFilterActive(f: SourceListFilters): boolean {
  return (
    f.caseReferenceLevels.length > 0 ||
    f.caseCourtLevels.length > 0 ||
    f.caseTrialProcedures.length > 0 ||
    f.caseJudgmentTime !== 'all'
  );
}

export function resolveItemLawEffectStatus(item: ReferenceSourceItem): LawEffectStatusFilter {
  if (item.lawEffectStatus) return item.lawEffectStatus;
  if (item.effectiveStatus && EFFECT_STATUS_LABEL_TO_KEY[item.effectiveStatus]) {
    return EFFECT_STATUS_LABEL_TO_KEY[item.effectiveStatus];
  }
  return 'effective';
}

export function resolveItemLawHierarchy(item: ReferenceSourceItem): LawHierarchyKey | null {
  if (item.lawHierarchyLevel) return item.lawHierarchyLevel;
  const head = item.metaLineParts?.[0];
  if (head && HIERARCHY_LABEL_TO_KEY[head]) return HIERARCHY_LABEL_TO_KEY[head];
  if (item.sourceType === 'judicial_interpretation' || item.title.includes('解释')) {
    return 'judicial_interpretation';
  }
  if (item.sourceType === 'law') return 'statute';
  return null;
}

export function shouldExpandLawFilterGroup(materialTypes: MaterialTypeKey[]): boolean {
  return materialTypes.includes('law');
}

export function shouldExpandCaseFilterGroup(materialTypes: MaterialTypeKey[]): boolean {
  return materialTypes.some((t) => t === 'case' || t === 'judgment');
}

export type AdvancedFilterGroupKey = 'web' | 'fabao' | 'kb' | 'law' | 'case';

export type AdvancedFilterOptionPools = {
  webTimeRanges: WebTimeRange[];
  fabaoDbKeys: string[];
  kbKeys: string[];
  lawEffectStatuses: LawEffectStatusFilter[];
  lawHierarchyLevels: LawHierarchyKey[];
  caseReferenceLevels: CaseReferenceLevelKey[];
  caseCourtLevels: CaseCourtLevelKey[];
  caseTrialProcedures: CaseTrialProcedureKey[];
  caseJudgmentTimeRanges: CaseJudgmentTimeRange[];
};

const CASE_JUDGMENT_TIME_KEYS: CaseJudgmentTimeRange[] = ['y1', 'y3', 'y5'];

export function getVisibleAdvancedFilterGroups(f: SourceListFilters): AdvancedFilterGroupKey[] {
  const groups: AdvancedFilterGroupKey[] = [];
  if (f.sourceScopes.includes('web')) groups.push('web');
  if (f.sourceScopes.includes('pkulaw')) groups.push('fabao');
  if (f.sourceScopes.includes('knowledge')) groups.push('kb');
  if (shouldExpandLawFilterGroup(f.materialTypes)) groups.push('law');
  if (shouldExpandCaseFilterGroup(f.materialTypes)) groups.push('case');
  return groups;
}

export function hasDrillDownRegularFilters(f: SourceListFilters): boolean {
  return getVisibleAdvancedFilterGroups(f).length > 0;
}

/** 取消常规筛选项时，同步清空对应高级筛选条件 */
export function syncAdvancedFiltersWithRegularFilters(f: SourceListFilters): SourceListFilters {
  const next: SourceListFilters = {
    ...f,
    fabaoSelectedKeys: [...f.fabaoSelectedKeys],
    kbSelectedKeys: [...f.kbSelectedKeys],
    lawHierarchyLevels: [...f.lawHierarchyLevels],
    caseReferenceLevels: [...f.caseReferenceLevels],
    caseCourtLevels: [...f.caseCourtLevels],
    caseTrialProcedures: [...f.caseTrialProcedures],
  };

  if (!f.sourceScopes.includes('web')) {
    next.webTime = 'all';
  }
  if (!f.sourceScopes.includes('pkulaw')) {
    next.fabaoSelectedKeys = [];
  }
  if (!f.sourceScopes.includes('knowledge')) {
    next.kbSelectedKeys = [];
  }
  if (!shouldExpandLawFilterGroup(f.materialTypes)) {
    next.lawEffectStatus = 'all';
    next.lawHierarchyLevels = [];
  }
  if (!shouldExpandCaseFilterGroup(f.materialTypes)) {
    next.caseReferenceLevels = [];
    next.caseCourtLevels = [];
    next.caseTrialProcedures = [];
    next.caseJudgmentTime = 'all';
  }

  return next;
}

function resolveKbFilterLabelFromSources(key: string, sources: ReferenceSourceItem[]): string {
  const fromOptions =
    KB_SCOPE_FILTER_OPTIONS.find((o) => o.key === key)?.label ??
    KB_FILTER_OPTIONS.find((o) => o.key === key)?.label;
  if (fromOptions) return fromOptions;

  const item = sources.find((s) => s.sourceScope === 'knowledge' && s.kbKey === key);
  return item?.knowledgeBaseName ?? item?.sourceLibraryName ?? key;
}

/** 基于当前来源快照生成高级筛选项（不随已应用筛选收缩） */
export function buildAdvancedFilterOptionPools(sources: ReferenceSourceItem[]): AdvancedFilterOptionPools {
  const webItems = sources.filter((item) => item.sourceScope === 'web');
  const webTimeRanges: WebTimeRange[] = ['all'];
  if (webItems.some((item) => (item.webAgeDays ?? 9999) <= 30)) webTimeRanges.push('d30');
  if (webItems.some((item) => (item.webAgeDays ?? 9999) <= 180)) webTimeRanges.push('d180');
  if (webItems.some((item) => (item.webAgeDays ?? 9999) <= 365)) webTimeRanges.push('d365');

  const fabaoDbKeys = Array.from(
    new Set(
      sources
        .filter((item) => item.sourceScope === 'pkulaw' && item.fabaoDbKey)
        .map((item) => item.fabaoDbKey as string)
    )
  );

  const kbKeys = Array.from(
    new Set(
      sources
        .filter((item) => item.sourceScope === 'knowledge' && item.kbKey)
        .map((item) => item.kbKey as string)
    )
  );

  const lawEffectStatusSet = new Set<LawEffectStatusFilter>();
  const lawHierarchySet = new Set<LawHierarchyKey>();
  for (const item of sources) {
    if (!isLawRegulationMaterial(item)) continue;
    lawEffectStatusSet.add(resolveItemLawEffectStatus(item));
    const hierarchy = resolveItemLawHierarchy(item);
    if (hierarchy) lawHierarchySet.add(hierarchy);
  }

  const caseItems = sources.filter((item) => isCaseJudgmentMaterial(item));
  const caseReferenceSet = new Set<CaseReferenceLevelKey>();
  const caseCourtSet = new Set<CaseCourtLevelKey>();
  const caseTrialSet = new Set<CaseTrialProcedureKey>();
  for (const item of caseItems) {
    const ref = resolveItemCaseReferenceLevel(item);
    if (ref) caseReferenceSet.add(ref);
    const court = resolveItemCaseCourtLevel(item);
    if (court) caseCourtSet.add(court);
    const trial = resolveItemCaseTrialProcedure(item);
    if (trial) caseTrialSet.add(trial);
  }

  const caseJudgmentTimeRanges: CaseJudgmentTimeRange[] = ['all'];
  for (const key of CASE_JUDGMENT_TIME_KEYS) {
    if (caseItems.some((item) => matchesCaseJudgmentTime(item, key))) {
      caseJudgmentTimeRanges.push(key);
    }
  }

  return {
    webTimeRanges,
    fabaoDbKeys,
    kbKeys,
    lawEffectStatuses: ['all', ...Array.from(lawEffectStatusSet)],
    lawHierarchyLevels: Array.from(lawHierarchySet),
    caseReferenceLevels: Array.from(caseReferenceSet),
    caseCourtLevels: Array.from(caseCourtSet),
    caseTrialProcedures: Array.from(caseTrialSet),
    caseJudgmentTimeRanges,
  };
}

/** 选择法规筛选项时，若资料类型未含法规，则自动勾选「法规」 */
export function syncMaterialTypesWithLawFilters(f: SourceListFilters): MaterialTypeKey[] {
  if (f.materialTypes.includes('law')) return f.materialTypes;

  const lawFilterActive = f.lawEffectStatus !== 'all' || f.lawHierarchyLevels.length > 0;
  if (!lawFilterActive) return f.materialTypes;

  return [...f.materialTypes, 'law'];
}

/** 选择案例筛选项时，若资料类型未含案例/裁判文书，则自动勾选 */
export function syncMaterialTypesWithCaseFilters(f: SourceListFilters): MaterialTypeKey[] {
  const hasCaseMaterial = f.materialTypes.some((t) => t === 'case' || t === 'judgment');
  if (hasCaseMaterial) return f.materialTypes;
  if (!isCaseFilterActive(f)) return f.materialTypes;

  const merged = new Set(f.materialTypes);
  merged.add('case');
  merged.add('judgment');
  return Array.from(merged);
}

export function defaultSourceListFilters(): SourceListFilters {
  return {
    resultStatus: 'all',
    matchMode: 'all',
    sourceScopes: [],
    materialTypes: [],
    fabaoSelectedKeys: [],
    kbSelectedKeys: [],
    webTime: 'all',
    lawEffectStatus: 'all',
    lawHierarchyLevels: [],
    caseReferenceLevels: [],
    caseCourtLevels: [],
    caseTrialProcedures: [],
    caseJudgmentTime: 'all',
  };
}

function matchesResultStatus(
  item: ReferenceSourceItem,
  f: SourceListFilters,
  options?: FilterReferenceSourcesOptions
): boolean {
  if (f.resultStatus === 'all') return true;
  const cited = !!item.citedMark;
  const inReferenceSet = options?.referenceSourceIds?.has(item.id) ?? false;

  if (options?.mode === 'match') {
    if (f.resultStatus === 'cited') return cited;
    if (f.resultStatus === 'referenced') return inReferenceSet && !cited;
    if (f.resultStatus === 'unreferenced') return !inReferenceSet;
    if (f.resultStatus === 'userSelected') return !!item.userPinned;
    return true;
  }

  if (f.resultStatus === 'cited') return cited;
  if (f.resultStatus === 'uncited') return !cited;
  if (f.resultStatus === 'userSelected') return !!item.userPinned;
  return true;
}

function matchesMatchMode(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (f.matchMode === 'all') return true;
  return item.matchType === f.matchMode;
}

function matchesSourceScope(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (f.sourceScopes.length === 0) return true;
  return f.sourceScopes.includes(item.sourceScope);
}

function itemMaterialFilterKey(item: ReferenceSourceItem): MaterialTypeKey {
  const { sourceType } = item;
  if (sourceType === 'knowledge' || sourceType === 'webpage') return 'other';
  if (sourceType === 'judicial_interpretation') return 'law';
  if (
    sourceType === 'law' ||
    sourceType === 'case' ||
    sourceType === 'judgment' ||
    sourceType === 'article' ||
    sourceType === 'other'
  ) {
    return sourceType;
  }
  return 'other';
}

function matchesMaterialType(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (f.materialTypes.length === 0) return true;
  return f.materialTypes.includes(itemMaterialFilterKey(item));
}

function matchesLawAdvanced(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (!shouldExpandLawFilterGroup(f.materialTypes)) return true;

  const lawFilterActive = f.lawEffectStatus !== 'all' || f.lawHierarchyLevels.length > 0;
  if (!lawFilterActive) return true;
  if (!isLawRegulationMaterial(item)) return false;

  if (f.lawEffectStatus !== 'all' && resolveItemLawEffectStatus(item) !== f.lawEffectStatus) {
    return false;
  }

  if (f.lawHierarchyLevels.length > 0) {
    const level = resolveItemLawHierarchy(item);
    if (!level || !f.lawHierarchyLevels.includes(level)) return false;
  }

  return true;
}

function matchesCaseAdvanced(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (!shouldExpandCaseFilterGroup(f.materialTypes) || !isCaseFilterActive(f)) return true;
  if (!isCaseJudgmentMaterial(item)) return false;

  if (f.caseReferenceLevels.length > 0) {
    const level = resolveItemCaseReferenceLevel(item);
    if (!level || !f.caseReferenceLevels.includes(level)) return false;
  }

  if (f.caseCourtLevels.length > 0) {
    const courtLevel = resolveItemCaseCourtLevel(item);
    if (!courtLevel || !f.caseCourtLevels.includes(courtLevel)) return false;
  }

  if (f.caseTrialProcedures.length > 0) {
    const procedure = resolveItemCaseTrialProcedure(item);
    if (!procedure || !f.caseTrialProcedures.includes(procedure)) return false;
  }

  if (!matchesCaseJudgmentTime(item, f.caseJudgmentTime)) return false;

  return true;
}

function fabaoSubMatches(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (!f.sourceScopes.includes('pkulaw')) return true;
  if (item.sourceScope !== 'pkulaw') return true;
  if (f.fabaoSelectedKeys.length === 0) return true;
  if (!item.fabaoDbKey) return false;
  return f.fabaoSelectedKeys.includes(item.fabaoDbKey);
}

function kbSubMatches(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (!f.sourceScopes.includes('knowledge')) return true;
  if (item.sourceScope !== 'knowledge') return true;
  if (f.kbSelectedKeys.length === 0) return true;
  return f.kbSelectedKeys.some((key) => {
    if (key === 'scope_personal' && item.kbScopeLabel === '个人知识库') return true;
    if (key === 'scope_team' && item.kbScopeLabel === '团队知识库') return true;
    return item.kbKey === key;
  });
}

function webMatchesTime(item: ReferenceSourceItem, f: SourceListFilters): boolean {
  if (!f.sourceScopes.includes('web')) return true;
  if (item.sourceScope !== 'web') return true;
  if (f.webTime === 'all') return true;

  const age = item.webAgeDays ?? 9999;
  switch (f.webTime) {
    case 'd30':
      return age <= 30;
    case 'd180':
      return age <= 180;
    case 'd365':
      return age <= 365;
    default:
      return true;
  }
}

export function filterReferenceSources(
  items: ReferenceSourceItem[],
  f: SourceListFilters,
  options?: FilterReferenceSourcesOptions
): ReferenceSourceItem[] {
  return items.filter(
    (item) =>
      matchesResultStatus(item, f, options) &&
      matchesMatchMode(item, f) &&
      matchesSourceScope(item, f) &&
      matchesMaterialType(item, f) &&
      matchesLawAdvanced(item, f) &&
      matchesCaseAdvanced(item, f) &&
      fabaoSubMatches(item, f) &&
      kbSubMatches(item, f) &&
      webMatchesTime(item, f)
  );
}

function citationOrder(mark?: string): number {
  if (!mark) return 999;
  const order = '①②③④⑤⑥⑦⑧⑨⑩'.indexOf(mark);
  return order >= 0 ? order : 999;
}

export function sortReferenceSources(items: ReferenceSourceItem[]): ReferenceSourceItem[] {
  return [...items].sort((a, b) => {
    const ac = !!a.citedMark;
    const bc = !!b.citedMark;
    if (ac !== bc) return ac ? -1 : 1;
    if (ac && bc) return citationOrder(a.citedMark) - citationOrder(b.citedMark);
    return b.relevance - a.relevance;
  });
}

function filtersEqual(a: SourceListFilters, b: SourceListFilters): boolean {
  return (
    a.resultStatus === b.resultStatus &&
    a.matchMode === b.matchMode &&
    a.webTime === b.webTime &&
    a.sourceScopes.join(',') === b.sourceScopes.join(',') &&
    a.materialTypes.join(',') === b.materialTypes.join(',') &&
    a.fabaoSelectedKeys.join(',') === b.fabaoSelectedKeys.join(',') &&
    a.kbSelectedKeys.join(',') === b.kbSelectedKeys.join(',') &&
    a.lawEffectStatus === b.lawEffectStatus &&
    a.lawHierarchyLevels.join(',') === b.lawHierarchyLevels.join(',') &&
    a.caseReferenceLevels.join(',') === b.caseReferenceLevels.join(',') &&
    a.caseCourtLevels.join(',') === b.caseCourtLevels.join(',') &&
    a.caseTrialProcedures.join(',') === b.caseTrialProcedures.join(',') &&
    a.caseJudgmentTime === b.caseJudgmentTime
  );
}

export function isDefaultSourceListFilters(f: SourceListFilters): boolean {
  return filtersEqual(f, defaultSourceListFilters());
}

export type ActiveFilterChip = { id: string; label: string };

/** 用于列表顶部可移除标签（每个标签对应一条生效条件） */
export function getActiveFilterChips(
  f: SourceListFilters,
  sources: ReferenceSourceItem[] = []
): ActiveFilterChip[] {
  const chips: ActiveFilterChip[] = [];
  if (f.resultStatus === 'cited') chips.push({ id: 'status:cited', label: '已引用' });
  if (f.resultStatus === 'uncited') chips.push({ id: 'status:uncited', label: '未引用' });
  if (f.resultStatus === 'referenced') chips.push({ id: 'status:referenced', label: '已参考' });
  if (f.resultStatus === 'unreferenced') chips.push({ id: 'status:unreferenced', label: '未参考' });
  if (f.resultStatus === 'userSelected') chips.push({ id: 'status:userSelected', label: '用户已选' });

  if (f.matchMode !== 'all') {
    const lab = MATCH_MODE_OPTIONS.find((o) => o.key === f.matchMode)?.label ?? f.matchMode;
    chips.push({ id: `match:${f.matchMode}`, label: lab });
  }

  for (const s of f.sourceScopes) {
    const lab = SOURCE_SCOPE_OPTIONS.find((o) => o.key === s)?.label ?? s;
    chips.push({ id: `scope:${s}`, label: lab });
  }

  for (const m of f.materialTypes) {
    const lab = MATERIAL_TYPE_OPTIONS.find((o) => o.key === m)?.label ?? m;
    chips.push({ id: `material:${m}`, label: lab });
  }

  for (const k of f.fabaoSelectedKeys) {
    const lab = FABAO_FILTER_OPTIONS.find((o) => o.key === k)?.label ?? k;
    chips.push({ id: `fabao:${k}`, label: `法宝数据库：${lab}` });
  }

  for (const k of f.kbSelectedKeys) {
    const lab = resolveKbFilterLabelFromSources(k, sources);
    chips.push({ id: `kb:${k}`, label: `知识库：${lab}` });
  }

  if (f.webTime !== 'all' && f.sourceScopes.includes('web')) {
    const lab = WEB_TIME_OPTIONS.find((o) => o.id === f.webTime)?.label ?? f.webTime;
    chips.push({ id: `web:${f.webTime}`, label: `全网：${lab}` });
  }

  if (f.lawEffectStatus !== 'all' && shouldExpandLawFilterGroup(f.materialTypes)) {
    const lab =
      LAW_EFFECT_STATUS_OPTIONS.find((o) => o.key === f.lawEffectStatus)?.label ?? f.lawEffectStatus;
    chips.push({ id: `lawEffect:${f.lawEffectStatus}`, label: lab });
  }

  if (shouldExpandLawFilterGroup(f.materialTypes)) {
    for (const level of f.lawHierarchyLevels) {
      const lab = LAW_HIERARCHY_OPTIONS.find((o) => o.key === level)?.label ?? level;
      chips.push({ id: `lawHierarchy:${level}`, label: lab });
    }
  }

  if (shouldExpandCaseFilterGroup(f.materialTypes)) {
    for (const level of f.caseReferenceLevels) {
      const lab = CASE_REFERENCE_LEVEL_OPTIONS.find((o) => o.key === level)?.label ?? level;
      chips.push({ id: `caseRef:${level}`, label: lab });
    }

    for (const level of f.caseCourtLevels) {
      const lab = CASE_COURT_LEVEL_OPTIONS.find((o) => o.key === level)?.label ?? level;
      chips.push({ id: `caseCourt:${level}`, label: lab });
    }

    for (const proc of f.caseTrialProcedures) {
      const lab = CASE_TRIAL_PROCEDURE_OPTIONS.find((o) => o.key === proc)?.label ?? proc;
      chips.push({ id: `caseProc:${proc}`, label: lab });
    }

    if (f.caseJudgmentTime !== 'all') {
      const lab =
        CASE_JUDGMENT_TIME_OPTIONS.find((o) => o.key === f.caseJudgmentTime)?.label ??
        f.caseJudgmentTime;
      chips.push({ id: `caseTime:${f.caseJudgmentTime}`, label: lab });
    }
  }

  return chips;
}

export function removeFilterChip(f: SourceListFilters, chipId: string): SourceListFilters {
  const next: SourceListFilters = {
    ...f,
    sourceScopes: [...f.sourceScopes],
    materialTypes: [...f.materialTypes],
    fabaoSelectedKeys: [...f.fabaoSelectedKeys],
    kbSelectedKeys: [...f.kbSelectedKeys],
    lawHierarchyLevels: [...f.lawHierarchyLevels],
    caseReferenceLevels: [...f.caseReferenceLevels],
    caseCourtLevels: [...f.caseCourtLevels],
    caseTrialProcedures: [...f.caseTrialProcedures],
  };

  if (
    chipId === 'status:cited' ||
    chipId === 'status:uncited' ||
    chipId === 'status:referenced' ||
    chipId === 'status:unreferenced' ||
    chipId === 'status:userSelected'
  ) {
    next.resultStatus = 'all';
    return next;
  }
  if (chipId.startsWith('match:')) {
    next.matchMode = 'all';
    return next;
  }
  if (chipId.startsWith('scope:')) {
    const key = chipId.slice('scope:'.length) as SourceScopeKey;
    next.sourceScopes = next.sourceScopes.filter((s) => s !== key);
    return syncAdvancedFiltersWithRegularFilters(next);
  }
  if (chipId.startsWith('material:')) {
    const key = chipId.slice('material:'.length) as MaterialTypeKey;
    next.materialTypes = next.materialTypes.filter((m) => m !== key);
    return syncAdvancedFiltersWithRegularFilters(next);
  }
  if (chipId.startsWith('fabao:')) {
    const key = chipId.slice('fabao:'.length);
    next.fabaoSelectedKeys = next.fabaoSelectedKeys.filter((k) => k !== key);
    return next;
  }
  if (chipId.startsWith('kb:')) {
    const key = chipId.slice('kb:'.length);
    next.kbSelectedKeys = next.kbSelectedKeys.filter((k) => k !== key);
    return next;
  }
  if (chipId.startsWith('web:')) {
    next.webTime = 'all';
    return next;
  }
  if (chipId.startsWith('lawEffect:')) {
    next.lawEffectStatus = 'all';
    return next;
  }
  if (chipId.startsWith('lawHierarchy:')) {
    const key = chipId.slice('lawHierarchy:'.length) as LawHierarchyKey;
    next.lawHierarchyLevels = next.lawHierarchyLevels.filter((k) => k !== key);
    return next;
  }
  if (chipId.startsWith('caseRef:')) {
    const key = chipId.slice('caseRef:'.length) as CaseReferenceLevelKey;
    next.caseReferenceLevels = next.caseReferenceLevels.filter((k) => k !== key);
    return next;
  }
  if (chipId.startsWith('caseCourt:')) {
    const key = chipId.slice('caseCourt:'.length) as CaseCourtLevelKey;
    next.caseCourtLevels = next.caseCourtLevels.filter((k) => k !== key);
    return next;
  }
  if (chipId.startsWith('caseProc:')) {
    const key = chipId.slice('caseProc:'.length) as CaseTrialProcedureKey;
    next.caseTrialProcedures = next.caseTrialProcedures.filter((k) => k !== key);
    return next;
  }
  if (chipId.startsWith('caseTime:')) {
    next.caseJudgmentTime = 'all';
    return next;
  }
  return next;
}
