export const SEARCH_ANSWER_EXECUTION_STEPS = [
  '正在理解问题意图…',
  '正在规划检索范围…',
  '正在检索法规库…',
  '正在检索案例库…',
  '正在检索知识库…',
  '正在整理参考来源…',
  '正在生成回答…',
] as const;

export const SEARCH_ANSWER_EXECUTION_STEP_MS = 1000;
export const SEARCH_ANSWER_STREAM_CHUNK_MS = 40;
export const SEARCH_ANSWER_STREAM_CHUNK_SIZE = 8;

export type TurnAnswerGenerationSnapshot = {
  stepIndex: number;
};

export function getExecutionStepMessage(stepIndex: number): string {
  const idx = Math.max(0, Math.min(stepIndex, SEARCH_ANSWER_EXECUTION_STEPS.length - 1));
  return SEARCH_ANSWER_EXECUTION_STEPS[idx];
}

type StartSearchAnswerGenerationOptions = {
  targetMarkdown: string;
  onStepChange: (stepIndex: number) => void;
  onStreamUpdate: (partialMarkdown: string) => void;
  onComplete: () => void;
};

/** 模拟执行步骤 + 流式输出；返回 cancel 函数 */
export function startSearchAnswerGeneration({
  targetMarkdown,
  onStepChange,
  onStreamUpdate,
  onComplete,
}: StartSearchAnswerGenerationOptions): () => void {
  let cancelled = false;
  let stepIndex = 0;
  let streamTimer: ReturnType<typeof setInterval> | null = null;

  onStepChange(0);

  const stepTimer = setInterval(() => {
    if (cancelled) return;
    if (stepIndex >= SEARCH_ANSWER_EXECUTION_STEPS.length - 1) return;
    stepIndex += 1;
    onStepChange(stepIndex);
  }, SEARCH_ANSWER_EXECUTION_STEP_MS);

  const stepsDuration =
    SEARCH_ANSWER_EXECUTION_STEPS.length * SEARCH_ANSWER_EXECUTION_STEP_MS;

  const streamTimeout = setTimeout(() => {
    if (cancelled) return;
    clearInterval(stepTimer);
    onStepChange(SEARCH_ANSWER_EXECUTION_STEPS.length - 1);

    if (!targetMarkdown) {
      onComplete();
      return;
    }

    let offset = 0;
    streamTimer = setInterval(() => {
      if (cancelled) return;
      offset = Math.min(targetMarkdown.length, offset + SEARCH_ANSWER_STREAM_CHUNK_SIZE);
      onStreamUpdate(targetMarkdown.slice(0, offset));
      if (offset >= targetMarkdown.length) {
        if (streamTimer) clearInterval(streamTimer);
        onComplete();
      }
    }, SEARCH_ANSWER_STREAM_CHUNK_MS);
  }, stepsDuration);

  return () => {
    cancelled = true;
    clearInterval(stepTimer);
    clearTimeout(streamTimeout);
    if (streamTimer) clearInterval(streamTimer);
  };
}
