import React, { useEffect, useMemo, useState } from 'react';
import {
  ArrowLeft,
  BookOpen,
  Check,
  ChevronLeft,
  ChevronRight,
  Edit3,
  Plus,
  ShieldCheck,
  Trash2,
  X,
} from 'lucide-react';
import {
  ContractPlaybook,
  DEFAULT_PLAYBOOK,
  OnboardingQuestion,
  PlaybookAnswers,
  REQUIRED_ONBOARDING_QUESTIONS,
  countFilledAnswers,
  createPlaybookFromAnswers,
  hasAnyAnswer,
  hasSeenOnboarding,
  loadPlaybooks,
  markOnboardingSeen,
  savePlaybooks,
  updatePlaybookFromAnswers,
} from './playbookOnboarding';

type ModalStep = 'select' | 'onboarding' | 'edit';

type ContractRiskModalProps = {
  open: boolean;
  onClose: () => void;
  onStartReview: (playbook: ContractPlaybook) => void;
};

type AnswerValue = PlaybookAnswers[string];

const emptyAnswer = (): AnswerValue => ({
  optionIds: [],
  customText: '',
  formValues: {},
  skipped: false,
});

function cloneAnswers(answers: PlaybookAnswers): PlaybookAnswers {
  return JSON.parse(JSON.stringify(answers || {}));
}

function getAnswer(answers: PlaybookAnswers, qid: string): AnswerValue {
  return answers[qid] || emptyAnswer();
}

export default function ContractRiskModal({ open, onClose, onStartReview }: ContractRiskModalProps) {
  const [step, setStep] = useState<ModalStep>('select');
  const [playbooks, setPlaybooks] = useState<ContractPlaybook[]>([]);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [draftAnswers, setDraftAnswers] = useState<PlaybookAnswers>({});
  const [currentAnswer, setCurrentAnswer] = useState(emptyAnswer());
  const [canLeaveOnboarding, setCanLeaveOnboarding] = useState(false);
  const [editingPlaybookId, setEditingPlaybookId] = useState<string | null>(null);
  const [playbookToDelete, setPlaybookToDelete] = useState<ContractPlaybook | null>(null);

  const questions = REQUIRED_ONBOARDING_QUESTIONS;
  const currentQuestion = questions[questionIndex];
  const isLastQuestion = questionIndex >= questions.length - 1;
  const progressPct = Math.round(((questionIndex + 1) / questions.length) * 100);
  const editingPlaybook = playbooks.find((p) => p.id === editingPlaybookId) || null;

  useEffect(() => {
    if (!open) return;
    const saved = loadPlaybooks();
    setPlaybooks(saved);
    setDraftAnswers({});
    setCurrentAnswer(emptyAnswer());
    setQuestionIndex(0);
    setEditingPlaybookId(null);
    setPlaybookToDelete(null);
    if (saved.length === 0 && !hasSeenOnboarding()) {
      setStep('onboarding');
      setCanLeaveOnboarding(false);
    } else {
      setStep('select');
      setCanLeaveOnboarding(true);
    }
  }, [open]);

  const answeredCount = useMemo(() => countFilledAnswers(draftAnswers), [draftAnswers]);

  if (!open) return null;

  const persistPlaybooks = (next: ContractPlaybook[]) => {
    setPlaybooks(next);
    savePlaybooks(next);
  };

  const startNewOnboarding = () => {
    setDraftAnswers({});
    setCurrentAnswer(emptyAnswer());
    setQuestionIndex(0);
    setEditingPlaybookId(null);
    setCanLeaveOnboarding(true);
    setStep('onboarding');
  };

  const goBackToSelect = () => {
    setStep('select');
    setDraftAnswers({});
    setCurrentAnswer(emptyAnswer());
    setQuestionIndex(0);
    setEditingPlaybookId(null);
  };

  const startEditPlaybook = (e: React.MouseEvent, pb: ContractPlaybook) => {
    e.stopPropagation();
    setEditingPlaybookId(pb.id);
    setDraftAnswers(cloneAnswers(pb.answers || {}));
    setStep('edit');
  };

  const openDeleteConfirm = (e: React.MouseEvent, pb: ContractPlaybook) => {
    e.stopPropagation();
    setPlaybookToDelete(pb);
  };

  const confirmDeletePlaybook = () => {
    if (!playbookToDelete) return;
    const next = playbooks.filter((p) => p.id !== playbookToDelete.id);
    persistPlaybooks(next);
    setPlaybookToDelete(null);
  };

  const syncCurrentIntoDraft = (answer: AnswerValue, qid: string) => {
    return { ...draftAnswers, [qid]: answer };
  };

  const finishOnboarding = (finalAnswers: PlaybookAnswers) => {
    markOnboardingSeen();
    if (!hasAnyAnswer(finalAnswers)) {
      goBackToSelect();
      return;
    }
    const pb = createPlaybookFromAnswers(finalAnswers);
    persistPlaybooks([pb, ...playbooks]);
    goBackToSelect();
  };

  const handleSaveEdit = () => {
    if (!editingPlaybookId) return;
    const cleaned: PlaybookAnswers = {};
    Object.entries(draftAnswers).forEach(([qid, ans]) => {
      if (!ans) return;
      const filled =
        (ans.optionIds && ans.optionIds.length > 0) ||
        !!(ans.customText && ans.customText.trim()) ||
        (ans.formValues && Object.values(ans.formValues).some((v) => v && String(v).trim()));
      cleaned[qid] = filled
        ? { ...ans, skipped: false }
        : { ...emptyAnswer(), skipped: true };
    });
    const next = playbooks.map((pb) =>
      pb.id === editingPlaybookId ? updatePlaybookFromAnswers(pb, cleaned) : pb
    );
    persistPlaybooks(next);
    goBackToSelect();
  };

  const loadAnswerForQuestion = (draft: PlaybookAnswers, qid: string) => {
    const saved = draft[qid];
    if (!saved || saved.skipped) return emptyAnswer();
    return {
      optionIds: saved.optionIds || [],
      customText: saved.customText || '',
      formValues: saved.formValues || {},
      skipped: false,
    };
  };

  const handleSkip = () => {
    const skipped = { ...emptyAnswer(), skipped: true };
    const nextDraft = syncCurrentIntoDraft(skipped, currentQuestion.id);
    setDraftAnswers(nextDraft);
    if (isLastQuestion) {
      finishOnboarding(nextDraft);
    } else {
      const nextIndex = questionIndex + 1;
      setQuestionIndex(nextIndex);
      setCurrentAnswer(loadAnswerForQuestion(nextDraft, questions[nextIndex].id));
    }
  };

  const handleSkipAll = () => {
    const nextDraft = { ...draftAnswers };
    for (let i = questionIndex; i < questions.length; i++) {
      const qid = questions[i].id;
      if (!nextDraft[qid] || nextDraft[qid].skipped) {
        nextDraft[qid] = { ...emptyAnswer(), skipped: true };
      }
    }
    nextDraft[currentQuestion.id] = { ...emptyAnswer(), skipped: true };
    finishOnboarding(nextDraft);
  };

  const canSubmitCurrent = (): boolean => {
    const q = currentQuestion;
    if (q.inputType === 'single') {
      return (currentAnswer.optionIds?.length || 0) === 1;
    }
    if (q.inputType === 'multi') {
      return (currentAnswer.optionIds?.length || 0) > 0 || !!(currentAnswer.customText || '').trim();
    }
    if (q.inputType === 'form') {
      const values = currentAnswer.formValues || {};
      const hasOptions =
        (currentAnswer.optionIds?.length || 0) > 0 || !!(currentAnswer.customText || '').trim();
      const hasForm = Object.values(values).some((v) => v && String(v).trim());
      if (q.id === 'liability_cap') {
        return !!(values.cap_floor && values.cap_floor.trim());
      }
      // escalation_and_approval 等：上报事项或多数字段任一有值即可
      return hasOptions || hasForm;
    }
    return false;
  };

  const handleNext = () => {
    if (!canSubmitCurrent()) return;
    const nextDraft = syncCurrentIntoDraft({ ...currentAnswer, skipped: false }, currentQuestion.id);
    setDraftAnswers(nextDraft);
    if (isLastQuestion) {
      finishOnboarding(nextDraft);
    } else {
      const nextIndex = questionIndex + 1;
      setQuestionIndex(nextIndex);
      setCurrentAnswer(loadAnswerForQuestion(nextDraft, questions[nextIndex].id));
    }
  };

  const handlePrev = () => {
    if (questionIndex <= 0) return;
    // 暂存当前题已填内容（不强制完整），便于返回后再前进时回填
    const nextDraft = syncCurrentIntoDraft({ ...currentAnswer, skipped: false }, currentQuestion.id);
    setDraftAnswers(nextDraft);
    const prevIndex = questionIndex - 1;
    setQuestionIndex(prevIndex);
    setCurrentAnswer(loadAnswerForQuestion(nextDraft, questions[prevIndex].id));
  };

  const toggleMultiOption = (optionId: string) => {
    setCurrentAnswer((prev) => {
      const set = new Set(prev.optionIds || []);
      if (set.has(optionId)) set.delete(optionId);
      else set.add(optionId);
      return { ...prev, optionIds: Array.from(set), skipped: false };
    });
  };

  const selectSingle = (optionId: string) => {
    setCurrentAnswer((prev) => ({
      ...prev,
      optionIds: [optionId],
      skipped: false,
    }));
  };

  const setFormValue = (fieldId: string, value: string) => {
    setCurrentAnswer((prev) => ({
      ...prev,
      formValues: { ...(prev.formValues || {}), [fieldId]: value },
      skipped: false,
    }));
  };

  /** 编辑页：按问题 id 更新 draftAnswers */
  const patchEditAnswer = (qid: string, patch: Partial<AnswerValue> | ((prev: AnswerValue) => AnswerValue)) => {
    setDraftAnswers((prev) => {
      const current = getAnswer(prev, qid);
      const next = typeof patch === 'function' ? patch(current) : { ...current, ...patch, skipped: false };
      return { ...prev, [qid]: next };
    });
  };

  const handleStartWithPlaybook = (pb: ContractPlaybook) => {
    onStartReview(pb);
  };

  const headerTitle =
    step === 'onboarding'
      ? '新建审查手册'
      : step === 'edit'
        ? '编辑审查手册'
        : '合同风控';

  const showBack = step === 'edit' || (step === 'onboarding' && canLeaveOnboarding);

  const renderPlaybookCard = (pb: ContractPlaybook, opts?: { isDefault?: boolean }) => (
    <div
      key={pb.id}
      role="button"
      tabIndex={0}
      onClick={() => handleStartWithPlaybook(pb)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleStartWithPlaybook(pb);
        }
      }}
      className={`p-5 rounded-2xl cursor-pointer hover:bg-white hover:shadow-xl transition-all border group relative flex flex-col h-full min-h-[160px] text-left ${
        opts?.isDefault
          ? 'bg-indigo-50/40 border-indigo-100 hover:border-indigo-300'
          : 'bg-slate-50 border-slate-100 hover:border-indigo-300'
      }`}
    >
      {!opts?.isDefault && (
        <div className="absolute top-5 right-5 flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-all z-10">
          <button
            type="button"
            onClick={(e) => startEditPlaybook(e, pb)}
            className="p-1.5 bg-slate-100 text-slate-400 rounded-full transition-all hover:!bg-indigo-100 hover:!text-indigo-600"
            title="编辑审查手册"
          >
            <Edit3 size={14} strokeWidth={2.5} />
          </button>
          <button
            type="button"
            onClick={(e) => openDeleteConfirm(e, pb)}
            className="p-1.5 bg-slate-100 text-slate-400 rounded-full transition-all hover:!bg-red-100 hover:!text-red-500"
            title="删除审查手册"
          >
            <Trash2 size={14} strokeWidth={2.5} />
          </button>
        </div>
      )}
      <div
        className={`w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-sm mb-4 transition-colors ${
          opts?.isDefault
            ? 'text-indigo-500 group-hover:text-indigo-600 group-hover:bg-indigo-50'
            : 'text-slate-400 group-hover:text-indigo-600 group-hover:bg-indigo-50'
        }`}
      >
        {opts?.isDefault ? (
          <ShieldCheck size={20} strokeWidth={2.5} />
        ) : (
          <BookOpen size={20} strokeWidth={2.5} />
        )}
      </div>
      <div className="flex items-start justify-between gap-2 mb-2">
        <h5 className="text-[15px] font-bold text-slate-800 group-hover:text-indigo-600 transition-colors pr-16">
          {pb.name}
        </h5>
        {opts?.isDefault && (
          <span className="shrink-0 text-[10px] px-2 py-0.5 rounded-md bg-indigo-100 text-indigo-600 font-extrabold">
            默认
          </span>
        )}
      </div>
      <p className="text-[13px] text-slate-500 leading-relaxed font-medium mt-auto line-clamp-3">
        {pb.desc}
      </p>
    </div>
  );

  const renderQuestionEditor = (
    q: OnboardingQuestion,
    answer: AnswerValue,
    onChange: (patch: Partial<AnswerValue> | ((prev: AnswerValue) => AnswerValue)) => void
  ) => (
    <div key={q.id} className="pb-8 mb-8 border-b border-slate-100 last:border-b-0 last:mb-0 last:pb-0">
      <h4 className="text-[16px] font-extrabold text-slate-800 mb-1.5 leading-snug">{q.title}</h4>
      {q.hint && <p className="text-[12px] text-slate-400 font-medium mb-4">{q.hint}</p>}

      {q.inputType === 'single' && (
        <div className="space-y-2">
          {q.options?.map((opt) => {
            const selected = answer.optionIds?.[0] === opt.id;
            return (
              <button
                key={opt.id}
                type="button"
                onClick={() => onChange({ optionIds: [opt.id], skipped: false })}
                className={`w-full text-left px-4 py-3 rounded-2xl border transition-all flex items-center gap-3 ${
                  selected
                    ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                    : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                }`}
              >
                <span
                  className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                  }`}
                >
                  {selected && <Check size={12} className="text-white" strokeWidth={3} />}
                </span>
                <span className="text-[13px] font-bold leading-relaxed">{opt.label}</span>
              </button>
            );
          })}
        </div>
      )}

      {q.inputType === 'multi' && (
        <div className="space-y-2">
          {q.options?.map((opt) => {
            const selected = (answer.optionIds || []).includes(opt.id);
            return (
              <button
                key={opt.id}
                type="button"
                onClick={() =>
                  onChange((prev) => {
                    const set = new Set(prev.optionIds || []);
                    if (set.has(opt.id)) set.delete(opt.id);
                    else set.add(opt.id);
                    return { ...prev, optionIds: Array.from(set), skipped: false };
                  })
                }
                className={`w-full text-left px-4 py-3 rounded-2xl border transition-all flex items-center gap-3 ${
                  selected
                    ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                    : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                }`}
              >
                <span
                  className={`w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 ${
                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                  }`}
                >
                  {selected && <Check size={12} className="text-white" strokeWidth={3} />}
                </span>
                <span className="text-[13px] font-bold leading-relaxed">{opt.label}</span>
              </button>
            );
          })}
          {q.allowCustom && (
            <input
              type="text"
              value={answer.customText || ''}
              onChange={(e) => onChange({ customText: e.target.value, skipped: false })}
              placeholder={q.customPlaceholder || '其他（可选）'}
              className="w-full mt-2 bg-white border border-slate-200 rounded-2xl px-4 py-3 text-[13px] text-slate-700 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 font-medium"
            />
          )}
        </div>
      )}

      {q.inputType === 'form' && (
        <div className="space-y-4">
          {q.optionsBeforeFields &&
            q.options &&
            renderFormMultiOptions(q, answer, onChange, 'text-[12px]')}
          {q.formFields?.map((field) => (
            <div key={field.id}>
              <label className="block text-[12px] font-bold text-slate-700 mb-2">{field.label}</label>
              {field.kind === 'select' ? (
                <div className="space-y-2">
                  {field.options?.map((opt) => {
                    const selected = answer.formValues?.[field.id] === opt.id;
                    return (
                      <button
                        key={opt.id}
                        type="button"
                        onClick={() =>
                          onChange((prev) => ({
                            ...prev,
                            formValues: { ...(prev.formValues || {}), [field.id]: opt.id },
                            skipped: false,
                          }))
                        }
                        className={`w-full text-left px-4 py-3 rounded-2xl border transition-all flex items-center gap-3 ${
                          selected
                            ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                            : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                        }`}
                      >
                        <span
                          className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                            selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                          }`}
                        >
                          {selected && <Check size={12} className="text-white" strokeWidth={3} />}
                        </span>
                        <span className="text-[13px] font-bold">{opt.label}</span>
                      </button>
                    );
                  })}
                </div>
              ) : (
                <input
                  type="text"
                  value={answer.formValues?.[field.id] || ''}
                  onChange={(e) =>
                    onChange((prev) => ({
                      ...prev,
                      formValues: { ...(prev.formValues || {}), [field.id]: e.target.value },
                      skipped: false,
                    }))
                  }
                  placeholder={field.placeholder}
                  className="w-full bg-white border border-slate-200 rounded-2xl px-4 py-3 text-[13px] text-slate-700 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 font-medium"
                />
              )}
            </div>
          ))}
          {!q.optionsBeforeFields &&
            q.options &&
            renderFormMultiOptions(q, answer, onChange, 'text-[12px]')}
        </div>
      )}
    </div>
  );

  function renderFormMultiOptions(
    q: OnboardingQuestion,
    answer: AnswerValue,
    onChange: (patch: Partial<AnswerValue> | ((prev: AnswerValue) => AnswerValue)) => void,
    labelClass: string
  ) {
    if (!q.options?.length) return null;
    return (
      <div>
        <label className={`block ${labelClass} font-bold text-slate-700 mb-2`}>
          {q.optionsLabel || '可多选'}
        </label>
        <div className="space-y-2">
          {q.options.map((opt) => {
            const selected = (answer.optionIds || []).includes(opt.id);
            return (
              <button
                key={opt.id}
                type="button"
                onClick={() =>
                  onChange((prev) => {
                    const set = new Set(prev.optionIds || []);
                    if (set.has(opt.id)) set.delete(opt.id);
                    else set.add(opt.id);
                    return { ...prev, optionIds: Array.from(set), skipped: false };
                  })
                }
                className={`w-full text-left px-4 py-3 rounded-2xl border transition-all flex items-center gap-3 ${
                  selected
                    ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                    : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                }`}
              >
                <span
                  className={`w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 ${
                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                  }`}
                >
                  {selected && <Check size={12} className="text-white" strokeWidth={3} />}
                </span>
                <span className="text-[13px] font-bold">{opt.label}</span>
              </button>
            );
          })}
        </div>
        {q.allowCustom && (
          <input
            type="text"
            value={answer.customText || ''}
            onChange={(e) => onChange({ customText: e.target.value, skipped: false })}
            placeholder={q.customPlaceholder || '其他（可选）'}
            className="w-full mt-3 bg-white border border-slate-200 rounded-2xl px-4 py-3 text-[13px] text-slate-700 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 font-medium"
          />
        )}
      </div>
    );
  }

  return (
    <div
      className="fixed inset-0 z-[600] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="bg-white w-[960px] max-h-[85vh] h-[800px] rounded-[32px] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 font-bold"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white z-10 shrink-0">
          <div className="flex items-center gap-3">
            {showBack && (
              <button
                onClick={goBackToSelect}
                className="p-1.5 -ml-2 mr-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 rounded-xl transition-colors"
              >
                <ArrowLeft size={20} strokeWidth={2.5} />
              </button>
            )}
            <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl">
              <ShieldCheck size={24} strokeWidth={2.5} />
            </div>
            <div>
              <h3 className="text-xl font-extrabold text-slate-800">{headerTitle}</h3>
              {step === 'onboarding' && (
                <p className="text-[12px] text-slate-400 font-bold mt-0.5">
                  按最新问卷配置审查规则；可随时跳过
                </p>
              )}
              {step === 'edit' && (
                <p className="text-[12px] text-slate-400 font-bold mt-0.5">
                  {editingPlaybook?.name || '调整选项后保存'}
                </p>
              )}
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {step === 'select' && (
          <div className="p-8 overflow-y-auto custom-scrollbar flex-1 bg-white animate-in fade-in duration-300">
            <div className="flex items-center justify-between mb-5">
              <div className="flex items-center gap-2 min-w-0">
                <BookOpen size={18} className="text-indigo-600 shrink-0" strokeWidth={2.5} />
                <h4 className="text-[16px] font-extrabold text-slate-800">审查手册</h4>
                <span className="text-[12px] text-slate-400 font-bold ml-1 truncate">
                  点击手册直接开启审查
                </span>
              </div>
              <button
                type="button"
                onClick={startNewOnboarding}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white border border-slate-200 text-slate-500 hover:text-indigo-600 hover:border-indigo-200 hover:bg-indigo-50 transition-all text-[12px] font-bold shadow-sm shrink-0"
              >
                <Plus size={14} strokeWidth={2.5} /> 新建
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {renderPlaybookCard(DEFAULT_PLAYBOOK, { isDefault: true })}
              {playbooks.map((pb) => renderPlaybookCard(pb))}
            </div>

            {playbooks.length === 0 && (
              <p className="mt-8 text-[13px] text-slate-400 font-medium leading-relaxed">
                可直接点击「默认审查手册」快速开审；或点右上角「新建」配置专属审查规则。
              </p>
            )}
          </div>
        )}

        {step === 'edit' && (
          <div className="flex flex-col flex-1 min-h-0 animate-in slide-in-from-right-8 duration-300">
            <div className="p-8 overflow-y-auto custom-scrollbar flex-1">
              {questions.map((q) =>
                renderQuestionEditor(q, getAnswer(draftAnswers, q.id), (patch) =>
                  patchEditAnswer(q.id, patch)
                )
              )}
            </div>
            <div className="px-8 py-5 border-t border-slate-100 flex items-center justify-end shrink-0 bg-white">
              <button
                type="button"
                onClick={handleSaveEdit}
                className="px-10 py-3.5 rounded-2xl font-bold transition-all flex items-center gap-2 bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-200 active:scale-95"
              >
                保存配置
              </button>
            </div>
          </div>
        )}

        {step === 'onboarding' && (
          <div className="flex flex-col flex-1 min-h-0 animate-in slide-in-from-right-8 duration-300">
            <div className="px-8 pt-6 shrink-0">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[12px] text-indigo-600 font-bold">
                  {questionIndex + 1} / {questions.length}
                </span>
                <span className="text-[12px] text-slate-400 font-bold">{progressPct}%</span>
              </div>
              <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                <div
                  className="h-full bg-indigo-600 transition-all duration-300"
                  style={{ width: `${progressPct}%` }}
                />
              </div>
            </div>

            <div className="p-8 overflow-y-auto custom-scrollbar flex-1">
              <h4 className="text-[18px] font-extrabold text-slate-800 mb-2 leading-snug">
                {currentQuestion.title}
              </h4>
              {currentQuestion.hint && (
                <p className="text-[13px] text-slate-400 font-medium mb-6">{currentQuestion.hint}</p>
              )}

              {currentQuestion.inputType === 'single' && (
                <div className="space-y-3">
                  {currentQuestion.options?.map((opt) => {
                    const selected = currentAnswer.optionIds?.[0] === opt.id;
                    return (
                      <button
                        key={opt.id}
                        type="button"
                        onClick={() => selectSingle(opt.id)}
                        className={`w-full text-left px-5 py-4 rounded-2xl border transition-all flex items-center gap-3 ${
                          selected
                            ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                            : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                        }`}
                      >
                        <span
                          className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                            selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                          }`}
                        >
                          {selected && <Check size={12} className="text-white" strokeWidth={3} />}
                        </span>
                        <span className="text-[14px] font-bold leading-relaxed">{opt.label}</span>
                      </button>
                    );
                  })}
                </div>
              )}

              {currentQuestion.inputType === 'multi' && (
                <div className="space-y-3">
                  {currentQuestion.options?.map((opt) => {
                    const selected = (currentAnswer.optionIds || []).includes(opt.id);
                    return (
                      <button
                        key={opt.id}
                        type="button"
                        onClick={() => toggleMultiOption(opt.id)}
                        className={`w-full text-left px-5 py-4 rounded-2xl border transition-all flex items-center gap-3 ${
                          selected
                            ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                            : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                        }`}
                      >
                        <span
                          className={`w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 ${
                            selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                          }`}
                        >
                          {selected && <Check size={12} className="text-white" strokeWidth={3} />}
                        </span>
                        <span className="text-[14px] font-bold leading-relaxed">{opt.label}</span>
                      </button>
                    );
                  })}
                  {currentQuestion.allowCustom && (
                    <input
                      type="text"
                      value={currentAnswer.customText || ''}
                      onChange={(e) =>
                        setCurrentAnswer((prev) => ({
                          ...prev,
                          customText: e.target.value,
                          skipped: false,
                        }))
                      }
                      placeholder={currentQuestion.customPlaceholder || '其他（可选）'}
                      className="w-full mt-2 bg-white border border-slate-200 rounded-2xl px-5 py-3.5 text-[14px] text-slate-700 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 font-medium"
                    />
                  )}
                </div>
              )}

              {currentQuestion.inputType === 'form' && (
                <div className="space-y-5">
                  {currentQuestion.optionsBeforeFields &&
                    currentQuestion.options &&
                    renderFormMultiOptions(
                      currentQuestion,
                      currentAnswer,
                      (patch) => {
                        setCurrentAnswer((prev) =>
                          typeof patch === 'function' ? patch(prev) : { ...prev, ...patch, skipped: false }
                        );
                      },
                      'text-[13px]'
                    )}
                  {currentQuestion.formFields?.map((field) => (
                    <div key={field.id}>
                      <label className="block text-[13px] font-bold text-slate-700 mb-2">
                        {field.label}
                      </label>
                      {field.kind === 'select' ? (
                        <div className="space-y-2">
                          {field.options?.map((opt) => {
                            const selected = currentAnswer.formValues?.[field.id] === opt.id;
                            return (
                              <button
                                key={opt.id}
                                type="button"
                                onClick={() => setFormValue(field.id, opt.id)}
                                className={`w-full text-left px-5 py-3.5 rounded-2xl border transition-all flex items-center gap-3 ${
                                  selected
                                    ? 'bg-indigo-50 border-indigo-300 text-indigo-700 shadow-sm'
                                    : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-slate-50'
                                }`}
                              >
                                <span
                                  className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                                    selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300'
                                  }`}
                                >
                                  {selected && (
                                    <Check size={12} className="text-white" strokeWidth={3} />
                                  )}
                                </span>
                                <span className="text-[14px] font-bold">{opt.label}</span>
                              </button>
                            );
                          })}
                        </div>
                      ) : (
                        <input
                          type="text"
                          value={currentAnswer.formValues?.[field.id] || ''}
                          onChange={(e) => setFormValue(field.id, e.target.value)}
                          placeholder={field.placeholder}
                          className="w-full bg-white border border-slate-200 rounded-2xl px-5 py-3.5 text-[14px] text-slate-700 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 font-medium"
                        />
                      )}
                    </div>
                  ))}
                  {!currentQuestion.optionsBeforeFields &&
                    currentQuestion.options &&
                    renderFormMultiOptions(
                      currentQuestion,
                      currentAnswer,
                      (patch) => {
                        setCurrentAnswer((prev) =>
                          typeof patch === 'function' ? patch(prev) : { ...prev, ...patch, skipped: false }
                        );
                      },
                      'text-[13px]'
                    )}
                </div>
              )}
            </div>

            <div className="px-8 py-5 border-t border-slate-100 flex items-center justify-between shrink-0 bg-white gap-3">
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={handleSkip}
                  className="px-4 py-2.5 rounded-xl text-[13px] font-bold text-slate-500 hover:bg-slate-50 hover:text-slate-700 transition-all"
                >
                  跳过此题
                </button>
                <button
                  type="button"
                  onClick={handleSkipAll}
                  className="px-4 py-2.5 rounded-xl text-[13px] font-bold text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all"
                >
                  全部跳过
                </button>
                {answeredCount > 0 && (
                  <span className="text-[11px] text-indigo-500 font-bold ml-1">
                    已答 {answeredCount} 题
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2">
                {questionIndex > 0 && (
                  <button
                    type="button"
                    onClick={handlePrev}
                    className="px-6 py-3.5 rounded-2xl font-bold transition-all flex items-center gap-1.5 border border-slate-200 text-slate-600 hover:bg-slate-50 hover:text-slate-800"
                  >
                    <ChevronLeft size={18} strokeWidth={2.5} />
                    上一题
                  </button>
                )}
                <button
                  type="button"
                  onClick={handleNext}
                  disabled={!canSubmitCurrent()}
                  className={`px-8 py-3.5 rounded-2xl font-bold transition-all flex items-center gap-2 ${
                    canSubmitCurrent()
                      ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-200 active:scale-95'
                      : 'bg-slate-100 text-slate-400 cursor-not-allowed border border-slate-200'
                  }`}
                >
                  {isLastQuestion ? '完成并创建' : '下一题'}
                  {!isLastQuestion && <ChevronRight size={18} strokeWidth={2.5} />}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {playbookToDelete && (
        <div
          className="fixed inset-0 z-[700] flex items-center justify-center bg-slate-900/40 backdrop-blur-md animate-in fade-in"
          onClick={() => setPlaybookToDelete(null)}
        >
          <div
            className="bg-white w-[400px] rounded-[32px] shadow-2xl p-8 animate-in zoom-in-95 font-bold"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mb-5">
                <Trash2 size={32} strokeWidth={2.5} />
              </div>
              <h3 className="text-xl font-extrabold text-slate-800 mb-2">确认删除吗？</h3>
              <p className="text-sm text-gray-400 font-bold px-4">
                您正在操作：<span className="text-slate-600">{playbookToDelete.name}</span>。
                <br />
                删除后该审查手册将无法恢复。
              </p>
            </div>
            <div className="mt-8 flex flex-col gap-2 font-bold px-4 pb-2">
              <button
                type="button"
                onClick={confirmDeletePlaybook}
                className="w-full py-4 bg-red-500 text-white rounded-2xl shadow-lg hover:bg-red-600 transition-transform"
              >
                确认删除
              </button>
              <button
                type="button"
                onClick={() => setPlaybookToDelete(null)}
                className="w-full py-3.5 rounded-2xl text-gray-400 hover:bg-slate-50"
              >
                我再想想
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
