/** 检索报告 WPS 预览演示正文（后续替换为真实 WPS 组件数据） */

export function buildSearchReportDocumentTitle(reportTitle: string): string {
  return reportTitle.replace(/^检索报告：/, '').replace(/\.docx$/i, '') || reportTitle;
}

export function buildSearchReportDocumentSections(query: string, reportTitle: string) {
  const topic = buildSearchReportDocumentTitle(reportTitle) || query || '本次检索主题';

  return {
    title: `${topic}检索分析报告`,
    sections: [
      {
        heading: '引言',
        paragraphs: [
          `本报告围绕「${query || topic}」检索问题，对现行法律法规、司法案例与实务观点进行系统梳理。报告旨在为后续法律分析、论证与文书起草提供可引用的结构化参考依据。`,
          '报告内容基于本轮检索召回的来源材料生成，已对引用关系、规范层级与案例要旨进行初步归纳，供进一步研判使用。',
        ],
      },
      {
        heading: '检索背景及争点归纳',
        subsections: [
          {
            subheading: '检索背景',
            numbered: [
              `检索主题：${topic}；`,
              '检索范围：本轮引用来源、全部参考来源及关联法规案例；',
              '检索目标：明确规范依据、类案裁判思路与可援引的核心观点。',
            ],
            bullets: [
              '结合用户问题与 AI 回答，提取需进一步验证的法律争点；',
              '对来源中的法规条文、案例要旨与实务文章进行交叉比对；',
              '形成可用于报告正文的章节骨架与引用清单。',
            ],
          },
          {
            subheading: '主要争点',
            bullets: [
              '相关规范如何适用，是否存在特别法优先或冲突规范；',
              '类案中对核心事实要件的认定标准与举证责任分配；',
              '诉讼/仲裁程序选择及管辖依据对实体结论的影响。',
            ],
          },
        ],
      },
      {
        heading: '规范与案例检索摘要',
        paragraphs: [
          '已检索并归纳与争点相关的法律规范、司法解释及指导性案例。对于存在多种解释路径的问题，报告中分别列明支持不同结论的主要理由及对应来源编号。',
          '如需展开某一来源的原文摘录或裁判要旨，可在正式版 WPS 组件中通过引用角标跳转至右侧参考来源列表。',
        ],
      },
    ],
  };
}
