import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import {
  ArrowLeft,
  Check,
  EyeOff,
  FileText,
  FolderOpen,
  FolderUp,
  Settings,
  Shield,
  ShieldCheck,
  X,
} from 'lucide-react';
import DefaultRuleSettingsPanel from './DefaultRuleSettingsPanel';
import {
  DEFAULT_DESENSITIZE_RULES,
  countDisplaySelected,
  getAllSelectionKeys,
  getDisplayFieldCount,
  toUniqueFieldIdsFromSelectionKeys,
} from './desensitizeRules';
import type { StartRecognizePayload } from './desensitizeRecognize';
import WorkspaceFilePicker, {
  isSameWorkspaceSelection,
  type WorkspaceFileSelection,
  type WorkspacePickerConclusion,
  type WorkspacePickerSource,
} from './WorkspaceFilePicker';

type DesensitizeModalProps = {
  open: boolean;
  onClose: () => void;
  sources?: WorkspacePickerSource[];
  conclusions?: WorkspacePickerConclusion[];
  onStartRecognize?: (payload: StartRecognizePayload) => void;
};

type ModalStep = 'main' | 'rule-settings';
type UploadTab = 'local' | 'workspace';

type PendingTarget =
  | {
      key: string;
      kind: 'local';
      name: string;
      size: number;
    }
  | {
      key: string;
      kind: 'workspace';
      selection: WorkspaceFileSelection;
    };

const MAX_TARGETS = 10;
const MAX_FILE_SIZE_BYTES = 100 * 1024 * 1024;
const ACCEPT_EXTENSIONS = ['.txt', '.doc', '.docx', '.pdf'] as const;
const ACCEPT_ATTR = ACCEPT_EXTENSIONS.join(',');

function workspaceTargetKey(selection: WorkspaceFileSelection): string {
  return `workspace:${selection.origin}:${selection.id}`;
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function getFileExtension(name: string): string {
  const idx = name.lastIndexOf('.');
  return idx >= 0 ? name.slice(idx).toLowerCase() : '';
}

function validateLocalFile(file: File): string | null {
  const ext = getFileExtension(file.name);
  if (!ACCEPT_EXTENSIONS.includes(ext as (typeof ACCEPT_EXTENSIONS)[number])) {
    return '仅支持 txt、doc、docx、纯文本 pdf 格式';
  }
  if (file.size > MAX_FILE_SIZE_BYTES) {
    return '单个文件不超过 100MB';
  }
  return null;
}

export default function DesensitizeModal({
  open,
  onClose,
  sources = [],
  conclusions = [],
  onStartRecognize,
}: DesensitizeModalProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const uploadTabListRef = useRef<HTMLDivElement>(null);
  const localTabRef = useRef<HTMLButtonElement>(null);
  const workspaceTabRef = useRef<HTMLButtonElement>(null);
  const [step, setStep] = useState<ModalStep>('main');
  const [activeTab, setActiveTab] = useState<UploadTab>('local');
  const [tabPillStyle, setTabPillStyle] = useState({ left: 4, width: 0 });
  const [pendingTargets, setPendingTargets] = useState<PendingTarget[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [selectedRuleIds, setSelectedRuleIds] = useState<string[]>(() =>
    DEFAULT_DESENSITIZE_RULES.filter((r) => r.isDefault).map((r) => r.id)
  );
  /** 已应用的 UI 勾选键（含复用字段的分类独立勾选）；执行时再收敛为唯一 fieldId */
  const [selectedFieldKeys, setSelectedFieldKeys] = useState<string[]>(() => getAllSelectionKeys());
  /** 配置页草稿：点「应用本次配置」才写回；返回则丢弃 */
  const [draftFieldKeys, setDraftFieldKeys] = useState<string[]>(() => getAllSelectionKeys());

  useEffect(() => {
    if (!open) return;
    const initialKeys = getAllSelectionKeys();
    setStep('main');
    setActiveTab('local');
    setPendingTargets([]);
    setIsDragging(false);
    setUploadError(null);
    setSelectedRuleIds(DEFAULT_DESENSITIZE_RULES.filter((r) => r.isDefault).map((r) => r.id));
    setSelectedFieldKeys(initialKeys);
    setDraftFieldKeys(initialKeys);
  }, [open]);

  const openRuleSettings = () => {
    setDraftFieldKeys([...selectedFieldKeys]);
    setStep('rule-settings');
  };

  const discardRuleSettings = () => {
    setDraftFieldKeys([...selectedFieldKeys]);
    setStep('main');
  };

  const applyRuleSettings = () => {
    if (draftFieldKeys.length === 0) return;
    setSelectedFieldKeys([...draftFieldKeys]);
    setStep('main');
  };

  const switchTab = (tab: UploadTab) => {
    setActiveTab(tab);
    setUploadError(null);
    setIsDragging(false);
  };

  useLayoutEffect(() => {
    if (!open || step !== 'main') return;
    const list = uploadTabListRef.current;
    const activeBtn = activeTab === 'local' ? localTabRef.current : workspaceTabRef.current;
    if (!list || !activeBtn) return;
    const listRect = list.getBoundingClientRect();
    const btnRect = activeBtn.getBoundingClientRect();
    setTabPillStyle({
      left: btnRect.left - listRect.left,
      width: btnRect.width,
    });
  }, [open, step, activeTab]);

  if (!open) return null;

  const onlyDefaultRules = DEFAULT_DESENSITIZE_RULES.every((r) => r.isDefault);
  const remainingSlots = MAX_TARGETS - pendingTargets.length;
  const atCapacity = remainingSlots <= 0;
  const workspaceSelections = pendingTargets
    .filter((t): t is Extract<PendingTarget, { kind: 'workspace' }> => t.kind === 'workspace')
    .map((t) => t.selection);

  const toggleRule = (ruleId: string) => {
    const rule = DEFAULT_DESENSITIZE_RULES.find((r) => r.id === ruleId);
    setSelectedRuleIds((prev) => {
      if (!prev.includes(ruleId)) return [...prev, ruleId];
      // 仅有默认规则时，默认规则不可取消选中
      if (rule?.isDefault && onlyDefaultRules) return prev;
      return prev.filter((id) => id !== ruleId);
    });
  };

  const hasSelectedTarget = pendingTargets.length > 0;
  const hasSelectedRules = selectedRuleIds.length > 0;
  const uniqueSelectedFieldIds = toUniqueFieldIdsFromSelectionKeys(selectedFieldKeys);
  const hasSelectedFields = uniqueSelectedFieldIds.length > 0;
  const canSubmit = hasSelectedTarget && hasSelectedRules && hasSelectedFields;
  const draftSelectedCount = countDisplaySelected(draftFieldKeys);
  const canApplyRuleSettings = draftSelectedCount > 0;

  const addLocalFiles = (fileList: FileList | File[]) => {
    const files = Array.from(fileList);
    if (files.length === 0) return;

    const next = [...pendingTargets];
    let rejectedFormat = false;
    let rejectedSize = false;
    let rejectedCapacity = false;

    for (const file of files) {
      if (next.length >= MAX_TARGETS) {
        rejectedCapacity = true;
        break;
      }
      const error = validateLocalFile(file);
      if (error === '仅支持 txt、doc、docx、纯文本 pdf 格式') {
        rejectedFormat = true;
        continue;
      }
      if (error === '单个文件不超过 100MB') {
        rejectedSize = true;
        continue;
      }
      const duplicated = next.some(
        (t) => t.kind === 'local' && t.name === file.name && t.size === file.size
      );
      if (duplicated) continue;
      next.push({
        key: `local:${file.name}:${file.size}:${file.lastModified}:${next.length}`,
        kind: 'local',
        name: file.name,
        size: file.size,
      });
    }

    if (rejectedCapacity) setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
    else if (rejectedFormat) setUploadError('仅支持 txt、doc、docx、纯文本 pdf 格式');
    else if (rejectedSize) setUploadError('单个文件不超过 100MB');
    else setUploadError(null);

    setPendingTargets(next);
  };

  const handleSelectFileClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (atCapacity) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    fileInputRef.current?.click();
  };

  const handleDropZoneClick = () => {
    if (atCapacity) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    fileInputRef.current?.click();
  };

  const handleLocalFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files?.length) return;
    addLocalFiles(files);
    e.target.value = '';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (!e.dataTransfer.files?.length) return;
    addLocalFiles(e.dataTransfer.files);
  };

  const removePendingTarget = (key: string) => {
    setPendingTargets((prev) => prev.filter((t) => t.key !== key));
    setUploadError(null);
  };

  const buildStartPayload = (mode: 'recognize' | 'direct-mask'): StartRecognizePayload => ({
    mode,
    targets: pendingTargets.map((target) => ({
      key: target.key,
      title: target.kind === 'local' ? target.name : target.selection.title,
      sourceLabel:
        target.kind === 'local'
          ? '本地文件'
          : target.selection.origin === 'source'
            ? '工作空间 · 来源文件'
            : '工作空间 · 生成结果',
    })),
    selectedFieldKeys,
  });

  const handleStartRecognize = () => {
    if (!canSubmit || !onStartRecognize) return;
    onStartRecognize(buildStartPayload('recognize'));
  };

  const handleStartDirectMask = () => {
    if (!canSubmit || !onStartRecognize) return;
    onStartRecognize(buildStartPayload('direct-mask'));
  };

  const handleWorkspaceToggle = (file: WorkspaceFileSelection) => {
    const exists = pendingTargets.some(
      (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file)
    );
    if (exists) {
      setUploadError(null);
      setPendingTargets((prev) =>
        prev.filter(
          (t) => !(t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file))
        )
      );
      return;
    }
    if (pendingTargets.length >= MAX_TARGETS) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    setPendingTargets((prev) => [
      ...prev,
      {
        key: workspaceTargetKey(file),
        kind: 'workspace',
        selection: file,
      },
    ]);
  };

  return (
    <div
      className="fixed inset-0 z-[600] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="bg-white w-[960px] max-h-[85vh] h-[800px] rounded-[32px] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 font-bold"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white z-10 shrink-0">
          <div className="flex items-center gap-3">
            {step === 'rule-settings' ? (
              <button
                type="button"
                onClick={discardRuleSettings}
                className="p-1.5 -ml-2 mr-1 text-slate-400 hover:bg-slate-100 hover:text-slate-600 rounded-xl transition-colors"
                aria-label="返回"
              >
                <ArrowLeft size={20} strokeWidth={2.5} />
              </button>
            ) : null}
            <div className="p-2 bg-rose-50 text-rose-600 rounded-xl">
              {step === 'rule-settings' ? (
                <Settings size={24} strokeWidth={2.5} />
              ) : (
                <EyeOff size={24} strokeWidth={2.5} />
              )}
            </div>
            <div>
              <h3 className="text-xl font-extrabold text-slate-800">
                {step === 'rule-settings' ? '默认脱敏规则' : '智能脱敏'}
              </h3>
              <p className="text-[12px] text-slate-400 font-bold mt-0.5">
                {step === 'rule-settings'
                  ? '勾选需要识别与脱敏的敏感字段类型'
                  : '上传文件并选择脱敏规则，识别或直接处理敏感信息'}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {step === 'rule-settings' ? (
          <div className="flex min-h-0 flex-1 flex-col p-8">
            <DefaultRuleSettingsPanel
              selectedKeys={draftFieldKeys}
              onChange={setDraftFieldKeys}
            />
          </div>
        ) : null}

        {step === 'main' ? (
        <div className="p-8 overflow-y-auto custom-scrollbar flex-1 space-y-8">
          {/* 上传区域 */}
          <section>
            <div className="mb-4 flex items-center justify-between gap-3">
              <h4 className="text-[15px] font-extrabold text-slate-800">选择脱敏对象</h4>
              <div
                ref={uploadTabListRef}
                className="relative flex items-center rounded-xl border border-slate-200 bg-slate-50/80 p-1"
              >
                <span
                  aria-hidden
                  className="pointer-events-none absolute top-1 bottom-1 rounded-lg bg-white shadow-sm transition-[left,width] duration-300 ease-out"
                  style={{ left: tabPillStyle.left, width: tabPillStyle.width }}
                />
                <button
                  ref={localTabRef}
                  type="button"
                  onClick={() => switchTab('local')}
                  className={`relative z-10 inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[12px] font-bold transition-colors duration-300 ${
                    activeTab === 'local' ? 'text-rose-700' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <FolderUp size={14} strokeWidth={2.5} />
                  本地上传
                </button>
                <button
                  ref={workspaceTabRef}
                  type="button"
                  onClick={() => switchTab('workspace')}
                  className={`relative z-10 inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[12px] font-bold transition-colors duration-300 ${
                    activeTab === 'workspace' ? 'text-rose-700' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <FolderOpen size={14} strokeWidth={2.5} />
                  工作空间文件
                </button>
              </div>
            </div>

            {activeTab === 'local' ? (
              <div className="animate-in fade-in duration-200">
                <div
                  role="button"
                  tabIndex={0}
                  onClick={handleDropZoneClick}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handleDropZoneClick();
                    }
                  }}
                  onDragOver={handleDragOver}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                  className={`relative flex min-h-[240px] flex-col items-center justify-center rounded-2xl border border-dashed px-6 py-10 text-center transition-all cursor-pointer ${
                    isDragging
                      ? 'border-rose-400 bg-rose-50/80 shadow-sm'
                      : 'border-slate-200 bg-gradient-to-b from-slate-50/80 to-white hover:border-rose-300 hover:bg-rose-50/40'
                  }`}
                >
                  <div className="relative mb-5 flex items-end justify-center">
                    <span className="relative flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-rose-500 to-rose-600 text-white shadow-lg shadow-rose-200">
                      <FolderUp size={30} strokeWidth={2.25} />
                      <span className="absolute -bottom-1 -right-1 flex h-7 w-7 items-center justify-center rounded-full bg-white shadow-md ring-2 ring-rose-100">
                        <ShieldCheck size={14} className="text-rose-600" strokeWidth={2.5} />
                      </span>
                    </span>
                  </div>

                  <p className="text-[16px] font-extrabold text-slate-800">
                    拖拽或{' '}
                    <button
                      type="button"
                      onClick={handleSelectFileClick}
                      className="text-rose-600 hover:text-rose-700 hover:underline underline-offset-2"
                    >
                      选择文件
                    </button>{' '}
                    至此处
                  </p>
                  <p className="mt-3 max-w-[520px] text-[12px] font-medium leading-relaxed text-slate-400">
                    支持 txt、doc、docx、纯文本 pdf 格式，单个文件不超过 100MB
                    <br />
                    本地与工作空间合计最多 {MAX_TARGETS} 个文件
                    {atCapacity ? '（已达上限）' : `（还可添加 ${remainingSlots} 个）`}
                  </p>

                  <input
                    ref={fileInputRef}
                    type="file"
                    className="hidden"
                    accept={ACCEPT_ATTR}
                    multiple
                    onChange={handleLocalFileChange}
                  />
                </div>

                {uploadError ? (
                  <p className="mt-3 text-[12px] font-bold text-red-500">{uploadError}</p>
                ) : null}
              </div>
            ) : (
              <div className="animate-in fade-in duration-200 space-y-3">
                <p className="text-[12px] font-medium text-slate-400">
                  本地与工作空间合计最多 {MAX_TARGETS} 个文件
                  {atCapacity ? '（已达上限）' : `（还可添加 ${remainingSlots} 个）`}
                </p>
                <WorkspaceFilePicker
                  sources={sources}
                  conclusions={conclusions}
                  selected={workspaceSelections}
                  onToggle={handleWorkspaceToggle}
                  disableAdd={atCapacity}
                />
                {uploadError ? (
                  <p className="text-[12px] font-bold text-red-500">{uploadError}</p>
                ) : null}
              </div>
            )}
          </section>

          {/* 待脱敏对象 */}
          <section>
            <div className="mb-3 flex items-center justify-between gap-3">
              <h4 className="text-[15px] font-extrabold text-slate-800">待脱敏对象</h4>
              <span className="text-[12px] font-bold text-slate-400">
                {pendingTargets.length}/{MAX_TARGETS}
              </span>
            </div>

            {pendingTargets.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50/50 px-4 py-8 text-center text-[12px] font-medium text-slate-400">
                从上方本地上传或工作空间选择文件后，将在此汇总展示
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                {pendingTargets.map((target) => {
                  const title = target.kind === 'local' ? target.name : target.selection.title;
                  const subtitle =
                    target.kind === 'local'
                      ? `本地文件 · ${formatFileSize(target.size)}`
                      : target.selection.origin === 'source'
                        ? '工作空间文件 · 来源文件'
                        : '工作空间文件 · 生成结果';
                  return (
                    <div
                      key={target.key}
                      className="flex items-center gap-3 rounded-2xl border border-slate-200 bg-white px-3.5 py-3 shadow-sm"
                    >
                      <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-rose-50 text-rose-600">
                        <FileText size={18} strokeWidth={2.5} />
                      </span>
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-[13px] font-bold text-slate-800">{title}</div>
                        <div className="mt-0.5 truncate text-[11px] font-medium text-slate-400">
                          {subtitle}
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={() => removePendingTarget(target.key)}
                        className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                        aria-label={`移除 ${title}`}
                      >
                        <X size={16} />
                      </button>
                    </div>
                  );
                })}
              </div>
            )}
          </section>

          {/* 脱敏规则 */}
          <section>
            <div className="mb-3 flex items-center gap-2">
              <Shield size={16} className="text-rose-600" strokeWidth={2.5} />
              <h4 className="text-[15px] font-extrabold text-slate-800">脱敏规则</h4>
            </div>

            <div className="grid grid-cols-1 gap-3">
              {DEFAULT_DESENSITIZE_RULES.map((rule) => {
                const selected = selectedRuleIds.includes(rule.id);
                const lockedDefault = Boolean(rule.isDefault && onlyDefaultRules && selected);
                const fieldTotal = getDisplayFieldCount();
                const fieldSelected = countDisplaySelected(selectedFieldKeys);
                return (
                  <div
                    key={rule.id}
                    className={`flex w-full items-start gap-3 rounded-2xl border p-4 transition-all ${
                      selected
                        ? 'border-rose-300 bg-rose-50/70 shadow-sm'
                        : 'border-slate-200 bg-white'
                    }`}
                  >
                    <button
                      type="button"
                      onClick={() => toggleRule(rule.id)}
                      aria-disabled={lockedDefault || undefined}
                      className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 transition-colors ${
                        selected ? 'border-rose-600 bg-rose-600' : 'border-slate-300 bg-white'
                      } ${lockedDefault ? 'cursor-default' : 'cursor-pointer'}`}
                      aria-label={selected ? '取消选择规则' : '选择规则'}
                    >
                      {selected ? <Check size={12} className="text-white" strokeWidth={3} /> : null}
                    </button>
                    <button
                      type="button"
                      onClick={() => toggleRule(rule.id)}
                      aria-disabled={lockedDefault || undefined}
                      className={`min-w-0 flex-1 text-left ${lockedDefault ? 'cursor-default' : ''}`}
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-[14px] font-extrabold text-slate-800">{rule.name}</span>
                        {rule.isDefault ? (
                          <span className="rounded-md bg-white px-1.5 py-0.5 text-[10px] font-extrabold text-rose-600 ring-1 ring-rose-200">
                            默认
                          </span>
                        ) : null}
                      </div>
                      <p className="mt-1.5 text-[12px] font-medium leading-relaxed text-slate-500">
                        {rule.description}
                      </p>
                      {rule.isDefault ? (
                        <p className="mt-2 text-[11px] font-bold text-rose-600/80">
                          已配置 {fieldSelected}/{fieldTotal} 个敏感字段
                        </p>
                      ) : null}
                    </button>
                    {rule.isDefault ? (
                      <div className="relative mt-0.5 shrink-0 group/settings">
                        <button
                          type="button"
                          onClick={openRuleSettings}
                          className="flex h-9 w-9 items-center justify-center rounded-xl border border-slate-200 bg-white text-slate-400 transition-all hover:border-rose-200 hover:bg-rose-50 hover:text-rose-600"
                          aria-label="配置脱敏字段"
                        >
                          <Settings size={16} strokeWidth={2.5} />
                        </button>
                        <span
                          role="tooltip"
                          className="pointer-events-none absolute right-0 bottom-full z-20 mb-2 whitespace-nowrap rounded-lg bg-slate-800 px-2.5 py-1.5 text-[11px] font-bold text-white opacity-0 shadow-lg transition-opacity duration-150 group-hover/settings:opacity-100"
                        >
                          配置脱敏字段
                          <span className="absolute right-3 top-full border-4 border-transparent border-t-slate-800" />
                        </span>
                      </div>
                    ) : null}
                  </div>
                );
              })}
            </div>
          </section>
        </div>
        ) : null}

        <div className="flex shrink-0 items-center justify-end gap-3 border-t border-slate-100 bg-white px-6 py-4">
          {step === 'rule-settings' ? (
            <div className="flex w-full items-center justify-end gap-3">
              {!canApplyRuleSettings ? (
                <p className="mr-auto text-[12px] font-bold text-slate-400">
                  请至少选择 1 个敏感字段
                </p>
              ) : null}
              <button
                type="button"
                disabled={!canApplyRuleSettings}
                onClick={applyRuleSettings}
                className={`rounded-2xl px-5 py-2.5 text-[13px] font-bold transition-all ${
                  canApplyRuleSettings
                    ? 'bg-rose-600 text-white shadow-lg shadow-rose-200 hover:bg-rose-700 active:scale-95'
                    : 'cursor-not-allowed bg-slate-100 text-slate-300'
                }`}
              >
                应用本次配置
              </button>
            </div>
          ) : (
            <>
              <button
                type="button"
                disabled={!canSubmit}
                onClick={handleStartRecognize}
                className={`rounded-2xl border px-5 py-2.5 text-[13px] font-bold transition-all ${
                  canSubmit
                    ? 'border-slate-200 bg-white text-slate-600 hover:bg-slate-50'
                    : 'cursor-not-allowed border-slate-100 bg-slate-50 text-slate-300'
                }`}
              >
                开始识别
              </button>
              <button
                type="button"
                disabled={!canSubmit}
                onClick={handleStartDirectMask}
                className={`rounded-2xl px-5 py-2.5 text-[13px] font-bold transition-all ${
                  canSubmit
                    ? 'bg-rose-600 text-white shadow-lg shadow-rose-200 hover:bg-rose-700 active:scale-95'
                    : 'cursor-not-allowed bg-slate-100 text-slate-300'
                }`}
              >
                直接脱敏
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
