import type { ReferenceSourceItem, SourceChannel } from './mockSearchResult';
import { FABAO_FILTER_OPTIONS } from './mockSearchResult';

export function scopeLabel(item: ReferenceSourceItem): string {
  switch (item.sourceScope) {
    case 'web':
      return '全网';
    case 'pkulaw':
      return '法宝数据库';
    case 'knowledge':
      return '知识库';
  }
}

/** @deprecated 使用 scopeLabel(item) */
export function scopeLabelFromChannel(channel: SourceChannel): string {
  switch (channel) {
    case 'web':
      return '全网';
    case 'fabao':
      return '法宝数据库';
    case 'kb':
      return '知识库';
  }
}

/** 列表主状态列：已引用 ＞ 已选 ＞ 可参考 */
export function primaryStatusLabel(item: ReferenceSourceItem): string {
  if (item.citedMark) return '已引用';
  if (item.userPinned) return '已选';
  return '可参考';
}

export function materialTypeColumnLabel(item: ReferenceSourceItem): string {
  if (item.materialTypeLabel) return item.materialTypeLabel;
  if (item.sourceScope === 'knowledge') return item.kbScopeLabel ?? '知识库资料';
  if (item.sourceScope === 'web') return item.sourceType === 'webpage' ? '网页资料' : '文章';
  return fabaoMaterialColumn(item.fabaoDbKey);
}

function fabaoMaterialColumn(key?: string): string {
  if (!key) return '案例库';
  if (key === 'court_case') return '裁判文书';
  if (key === 'regulation' || key === 'legislation' || key === 'labor') return '法规';
  if (key === 'journal' || key === 'lawyer') return '文章';
  if (key === 'case' || key === 'typical' || key === 'guiding') return '案例库';
  return FABAO_FILTER_OPTIONS.find((o) => o.key === key)?.label ?? '案例库';
}

const matchTypeLabelMap: Record<ReferenceSourceItem['matchType'], string> = {
  web: '全网匹配',
  case: '类案匹配',
  law: '法规匹配',
  law_article: '法条内容匹配',
  law_history: '法规沿革匹配',
  law_relation: '法规关联匹配',
};

export function matchTypeLabel(m: ReferenceSourceItem['matchType']): string {
  return matchTypeLabelMap[m];
}

export function formatMetaLine(parts: string[]): string {
  return parts.join('｜');
}

/**
 * 合并「来源范围 + 资料类型」为一行展示（如 法宝数据库+案例库 → 法宝案例库）
 */
export function mergedSourceLine(item: ReferenceSourceItem): string {
  if (item.sourceScope === 'web') return item.sourceType === 'webpage' ? '全网网页' : '全网文章';
  if (item.sourceScope === 'knowledge') {
    if (item.kbScopeLabel) return item.kbScopeLabel;
    return item.materialTypeLabel ?? '知识库资料';
  }
  const key = item.fabaoDbKey;
  const mat = materialTypeColumnLabel(item);
  if (key === 'court_case' || mat === '裁判文书') return '法宝裁判文书';
  if (key === 'regulation' || key === 'legislation' || key === 'labor' || mat === '法规') {
    return '法宝法规库';
  }
  if (key === 'journal' || key === 'lawyer' || mat === '文章') return '法宝文章库';
  if (key === 'case' || key === 'typical' || key === 'guiding' || mat === '案例库') {
    return '法宝案例库';
  }
  return mat ? `法宝 · ${mat}` : '法宝数据库';
}

/** 第二行：来源库类型｜元信息（法院、年份、案由等） */
export function buildSourceDetailLine(item: ReferenceSourceItem): string {
  const head = mergedSourceLine(item);
  if (item.metaLineParts?.length) {
    return [head, ...item.metaLineParts].join('｜');
  }
  return head;
}

/** 第三行匹配方式前缀样式 */
export function matchTypePrefixClass(m: ReferenceSourceItem['matchType']): string {
  switch (m) {
    case 'web':
      return 'font-extrabold text-blue-600';
    case 'case':
      return 'font-extrabold text-teal-600';
    case 'law':
      return 'font-extrabold text-emerald-600';
    case 'law_article':
      return 'font-extrabold text-violet-600';
    case 'law_history':
      return 'font-extrabold text-amber-600';
    case 'law_relation':
      return 'font-extrabold text-rose-600';
  }
}

/** 「命中片段」展示文案：优先 hitSnippet，否则从摘要去掉标题前缀 */
export function hitDisplayText(item: ReferenceSourceItem): string {
  if (item.hitSnippet) return item.hitSnippet;
  return stripTitlePrefix(item.snippet);
}

function stripTitlePrefix(snippet: string): string {
  const s = snippet.replace(/^标题:\s*[^。]+。\s*/, '').replace(/^节选[：:]\s*/, '').trim();
  return s || snippet;
}
