import React, { useLayoutEffect, useRef, useState } from 'react';
import { fitHitSnippetBody } from './hitSnippetFit';

type HitSnippetPreviewProps = {
  matchLabel: string;
  matchLabelClass: string;
  text: string;
};

const HitSnippetPreview: React.FC<HitSnippetPreviewProps> = ({
  matchLabel,
  matchLabelClass,
  text,
}) => {
  const ref = useRef<HTMLParagraphElement>(null);
  const [visibleBody, setVisibleBody] = useState(text);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    const update = () => {
      const style = window.getComputedStyle(el);
      const font = style.font;
      const prefix = `${matchLabel}：`;
      setVisibleBody(fitHitSnippetBody(prefix, text, el.clientWidth, font, 2));
    };

    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [text, matchLabel]);

  return (
    <p
      ref={ref}
      className="mt-1.5 w-full min-w-0 break-words text-[11px] font-medium leading-relaxed text-slate-600"
      title={text}
    >
      <span className={matchLabelClass}>{matchLabel}：</span>
      {visibleBody}
    </p>
  );
};

export default HitSnippetPreview;
